window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[76]={"id":"076","numero":76,"titre":"Addiction à l'alcool","objectifs":[{"id":"76-1","rang":"A","rubrique":"Épidémiologie","titre":"Connaître les principaux chiffres liés à la consommation d’alcool en France (sources BEH 2019)","contenu":"<p>L’<span class=\"kw-etio\">alcool</span> est la <strong>substance psychoactive la plus consommée en France</strong>, qui figure parmi <span class=\"kw-clinique\">les</span> pays à plus forte consommation (sources BEH 2019).</p>\n      <table >\n        <thead><tr><th>Indicateur</th><th>Chiffre (adultes, France)</th></tr></thead>\n        <tbody>\n          <tr><td>Consommation au moins <span class=\"kw-chiffre\">1 ×/an</span></td><td><span class=\"kw-chiffre\">90 %</span> des adultes</td></tr>\n          <tr><td>Consommation <strong>quotidienne</strong></td><td><span class=\"kw-chiffre\">10 %</span> — prédominance masculine (<span class=\"kw-chiffre\">3 H pour 1 F</span>)</td></tr>\n          <tr><td>Ivresse dans l’année</td><td><span class=\"kw-chiffre\">1 sur 5</span></td></tr>\n          <tr><td>Dépassement des repères de l’usage à faible risque</td><td><span class=\"kw-chiffre\">≥ 1 sur 5</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Selon l’âge :</strong></p>\n      <ul>\n        <li>Consommations <strong>régulières</strong> : plutôt <span class=\"kw-clinique\">les</span> personnes de <span class=\"kw-chiffre\">≥ 65 ans</span>.</li>\n        <li>Alcoolisations ponctuelles importantes (API) et ivresses ponctuelles : surtout chez <span class=\"kw-clinique\">les</span> <strong>jeunes adultes</strong>.</li>\n      </ul>\n      <p><strong>Accès aux soins :</strong> à peine <span class=\"kw-chiffre\">10 %</span> des patients souffrant de troubles liés à l’usage d’<span class=\"kw-etio\">alcool</span> accèdent à des soins spécialisés.</p>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-def\">Mortalité</span>.</strong> L’<span class=\"kw-etio\">alcool</span> est la <strong>2ᵉ cause de mortalité évitable</strong> (après le <span class=\"kw-etio\">tabagisme</span>) : <span class=\"kw-alerte\">41 000 décès/an</span> attribuables à l’<span class=\"kw-etio\">alcool</span> en France (cancers, maladies hépatiques, maladies cardiovasculaires, accidents, suicides). La part de mortalité évitable attribuable à l’<span class=\"kw-etio\">alcool</span> est particulièrement élevée chez <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">20-39 ans</span> (<span class=\"kw-chiffre\">25 %</span>). L’<span class=\"kw-etio\">alcoolisme</span> est la cause directe de <span class=\"kw-chiffre\">15-25 %</span> des hospitalisations.\n      </div>","frequence":0},{"id":"76-2","rang":"A","rubrique":"Définition","titre":"Connaître les définitions : addictologie, non usage, usage à faible risque, mésusage, usage à risque, usage nocif (CIM11), dépendance (CIM 11)","contenu":"<p>L’<span class=\"kw-def\">addictologie</span> est la discipline qui prend en charge <span class=\"kw-clinique\">les</span> conduites addictives. La consommation de substances psychoactives se décline sur un <strong>continuum</strong> : on distingue trois grands comportements — le <strong>non-usage</strong>, l’<strong>usage à faible risque</strong> et le <strong>mésusage</strong>.</p>\n      <table >\n        <thead><tr><th>Notion</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Verre standard</span></td><td><strong>1 <span class=\"kw-def\">verre standard</span> = <span class=\"kw-chiffre\">10 g d’alcool pur</span></strong> (quantité réglementaire servie dans un débit de boisson). Formule : quantité (L) × 8 × degré. Ex. : 10 cl de vin, 25 cl de bière à 4°, 3 cl de whisky à 40° ; une bouteille de 75 cl de vin à 12° ≈ 7 verres standard.</td></tr>\n          <tr><td><span class=\"kw-def\">Non-usage</span></td><td>Situations où il est <strong>recommandé de ne pas consommer</strong> : femme enceinte / projet de <span class=\"kw-ci\">grossesse</span> / allaitement ; jeunes et adolescents ; conduite automobile, manipulation d’outils ou de machines ; sports à risque ; certains médicaments ou pathologies.</td></tr>\n          <tr><td><span class=\"kw-def\">Usage à faible risque</span></td><td>Consommation respectant <span class=\"kw-clinique\">les</span> repères : <span class=\"kw-chiffre\">≤ 10 verres/semaine</span>, <span class=\"kw-chiffre\">≤ 2 verres/jour</span>, avec des <span class=\"kw-def\">jours sans consommation</span>. (Pour les substances psychoactives, l’usage à faible risque <strong>n’est défini que pour l’<span class=\"kw-etio\">alcool</span></strong>.)</td></tr>\n          <tr><td><span class=\"kw-def\">Mésusage</span></td><td>Toute consommation <strong>supérieure aux repères de l’usage à faible risque</strong> ; caractérisée par l’existence de <strong>risques et/ou de dommages et/ou de dépendance</strong>. Il se décline en usage à risque, usage nocif et dépendance.</td></tr>\n          <tr><td><span class=\"kw-def\">Usage à risque</span></td><td>Niveaux de consommation qui <strong>exposent à des complications</strong> (aiguës ou chroniques) <strong>non encore présentes</strong> (et qui ne le seront peut-être jamais). Ce n’est <strong>pas un trouble</strong> médical mais un <strong><span class=\"kw-def\">facteur de risque</span> pré-morbide</strong> (OMS) à repérer.</td></tr>\n          <tr><td><span class=\"kw-def\">Usage nocif</span> <em>(CIM)</em></td><td>Mode de consommation <strong>préjudiciable à la santé</strong> : complications <strong>physiques ou psychiques avérées</strong>, mais <strong>sans <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">critères de</span> la dépendance</strong>. C’est un trouble lié à l’usage, mais pas une addiction.</td></tr>\n          <tr><td><span class=\"kw-def\">Dépendance</span> <em>(CIM)</em></td><td><strong><span class=\"kw-clinique\">Syndrome de dépendance</span></strong> : ensemble de phénomènes comportementaux, cognitifs et physiologiques où l’usage entraîne un <strong>désinvestissement progressif des autres activités</strong>. Diagnostic si <span class=\"kw-chiffre\">≥ 3 / 6 critères</span> sur <span class=\"kw-chiffre\">12 mois</span>. Correspond au trouble de l’usage <span class=\"kw-def\">DSM-5</span> <strong>modéré à sévère</strong>.</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"76-3","rang":"A","rubrique":"Définition","titre":"Connaître les éléments de comparaison de la dépendance (CIM 11) et du trouble de l’usage de l’alcool (DSM5)","contenu":"<p><span class=\"kw-clinique\">Les</span> deux classifications utilisent <strong>globalement les mêmes critères</strong> mais avec une logique différente : la <span class=\"kw-def\">CIM</span> oppose <strong>usage nocif</strong> et <strong><span class=\"kw-clinique\">syndrome de dépendance</span></strong> (catégoriel, <span class=\"kw-chiffre\">≥ 3 / 6 critères</span>) ; le <span class=\"kw-def\">DSM-5</span> définit un <strong><span class=\"kw-def\">trouble de l’usage de l’alcool</span></strong> en <strong>continuum</strong> de sévérité (<span class=\"kw-chiffre\">11 critères</span>, sur <span class=\"kw-chiffre\">12 mois</span>).</p>\n      <div class=\"callout callout-info\">\n        <strong>Pont entre <span class=\"kw-clinique\">les</span> deux.</strong> La <strong>dépendance (CIM)</strong> correspond aux troubles de l’usage <strong>DSM-5 modérés à sévères</strong>. L’usage nocif (CIM) se rapproche d’un trouble léger sans signe physiologique de dépendance.\n      </div>\n      <p><strong>Mise en regard des 11 critères DSM-5 et des 6 <span class=\"kw-def\">critères de</span> dépendance CIM :</strong></p>\n      <table >\n        <thead><tr><th>Critère</th><th>DSM-5 (11 critères)</th><th>CIM — dépendance (6 critères)</th></tr></thead>\n        <tbody>\n          <tr><td>Échecs répétés des obl<span class=\"kw-chiffre\">iga</span>tions (travail, école, maison)</td><td>✔</td><td>—</td></tr>\n          <tr><td>Consommation répétée en situation <span class=\"kw-alerte\">dangereuse</span> (ex. conduite)</td><td>✔</td><td>—</td></tr>\n          <tr><td>Consommation malgré des difficultés sociales / relationnelles persistantes</td><td>✔</td><td>—</td></tr>\n          <tr><td>Consommation persistante malgré des problèmes physiques / psychiatriques</td><td>✔</td><td>✔ (poursuite malgré conséquences nocives)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Perte de contrôle</span> : quantité / durée &gt; prévu</td><td>✔</td><td>✔ (difficultés à contrôler l’usage)</td></tr>\n          <tr><td>Désir / tentatives infructueuses de réduire ou contrôler</td><td>✔</td><td>✔ (difficultés à contrôler l’usage)</td></tr>\n          <tr><td>Temps considérable consacré à la consommation / récupération</td><td>✔</td><td>✔ (abandon des autres intérêts)</td></tr>\n          <tr><td>Abandon / <span class=\"kw-ttt\">réduction</span> d’activités importantes au profit de l’<span class=\"kw-etio\">alcool</span></td><td>✔</td><td>✔ (abandon des autres intérêts)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Tolérance</span> / accoutumance</td><td>✔</td><td>✔</td></tr>\n          <tr><td><span class=\"kw-clinique\">Sevrage</span> à l’arrêt</td><td>✔</td><td>✔</td></tr>\n          <tr><td><span class=\"kw-clinique\">Craving</span> : envie impérieuse, pulsion irrépressible</td><td>✔</td><td>✔ (désir puissant / compulsif)</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Seuil DSM-5 (continuum)</th><th>Nombre de critères</th><th>Équivalence CIM</th></tr></thead>\n        <tbody>\n          <tr><td>Trouble léger</td><td><span class=\"kw-chiffre\">2 à 3 critères</span></td><td>≈ usage nocif</td></tr>\n          <tr><td>Trouble modéré</td><td><span class=\"kw-chiffre\">4 à 5 critères</span></td><td rowspan=\"2\">≈ <strong>dépendance</strong> (<span class=\"kw-chiffre\">≥ 3</span> / 6 critères CIM)</td></tr>\n          <tr><td>Trouble sévère</td><td><span class=\"kw-chiffre\">≥ 6 critères</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"76-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les repères de consommation d’alcool définissant l’usage à faible risque","contenu":"<p>La consommation dite <strong>« à faible risque »</strong> repose sur trois repères simples (recommandations de <span class=\"kw-def\">Santé publique France</span>).</p>\n      <ul>\n        <li>Ne pas consommer <span class=\"kw-chiffre\">plus de 10 verres standard par semaine</span>.</li>\n        <li>Ne pas consommer <span class=\"kw-chiffre\">plus de 2 verres standard par jour</span>.</li>\n        <li>Avoir des <strong><span class=\"kw-def\">jours sans consommation</span></strong> dans la semaine.</li>\n      </ul>\n      <p>En cas de consommation occasionnelle, recommandations complémentaires :</p>\n      <ul>\n        <li>Réduire la quantité totale d’<span class=\"kw-etio\">alcool</span> bue à chaque occasion.</li>\n        <li>Boire lentement, en mangeant et en alternant avec de l’eau.</li>\n        <li>Éviter <span class=\"kw-clinique\">les</span> lieux et activités à risque.</li>\n        <li>S’assurer de la présence de personnes de confiance et d’un retour sécurisé.</li>\n      </ul>","frequence":1},{"id":"76-5","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer usage nocif et dépendance selon les critères de la CIM 11","contenu":"<p><span class=\"kw-def\">Usage nocif</span> et <span class=\"kw-def\">dépendance</span> constituent <span class=\"kw-clinique\">les</span> <strong>deux types de troubles liés à l’usage</strong> d’une substance. Un usage nocif n’est donc <strong>pas une addiction</strong>, mais ses répercussions en font tout de même un « trouble » ; l’<span class=\"kw-def\">usage à risque</span>, lui, n’est <strong>pas un trouble</strong> médical mais un simple <span class=\"kw-def\">facteur de risque</span> pré-morbide à repérer.</p>\n      <table >\n        <thead><tr><th>Trouble (CIM)</th><th><span class=\"kw-def\">Critère diagnostique</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Usage nocif</span> pour la santé</td><td>Mode de consommation <strong>préjudiciable à la santé</strong> : complications <strong>physiques ou psychiques avérées</strong> (et/ou sociales), <strong>SANS</strong> <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">critères de</span> la <span class=\"kw-def\">dépendance</span>. Le patient ne fait souvent pas le lien entre le dommage et sa consommation.</td></tr>\n          <tr><td><span class=\"kw-def\">Syndrome de dépendance</span></td><td>Ensemble de phénomènes <strong>comportementaux, cognitifs et physiologiques</strong> où l’usage de la substance entraîne un <strong>désinvestissement progressif</strong> des autres activités. Diagnostic de certitude : <strong><span class=\"kw-chiffre\">≥ 3 des 6 manifestations</span></strong> ci-dessous, présentes ensemble <strong>au cours de la dernière année</strong>.</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-clinique\">Les</span> 6 <span class=\"kw-def\">critères de</span> dépendance (CIM) :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Craving</span> : désir puissant ou compulsif d’utiliser la substance.</li>\n        <li><strong>Difficultés à contrôler l’usage</strong> (début, interruption, niveaux de consommation).</li>\n        <li><span class=\"kw-clinique\">Syndrome de sevrage</span> physiologique à la diminution / l’arrêt (ou usage pour soulager / éviter le <span class=\"kw-ttt\">sevrage</span>).</li>\n        <li><span class=\"kw-clinique\">Tolérance</span> : besoin d’une quantité plus importante pour obtenir l’effet désiré.</li>\n        <li><strong>Abandon progressif des autres sources de plaisir et d’intérêts</strong> au profit de l’usage ; temps croissant passé à se procurer / consommer la substance ou à récupérer de ses effets.</li>\n        <li><strong>Poursuite de la consommation malgré des conséquences manifestement nocives</strong> (dont le sujet est, ou devrait être, conscient).</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> La <span class=\"kw-def\">dépendance</span> (CIM) correspond aux troubles de l’usage <span class=\"kw-def\">DSM-5</span> <strong>modérés à sévères</strong>. <span class=\"kw-clinique\">Les</span> 6 critères se regroupent en 3 dimensions : <strong>altération du contrôle</strong> de l’usage, <strong>priorité croissante</strong> donnée à l’usage, et <strong>signes physiologiques</strong> (<span class=\"kw-clinique\">tolérance</span>, <span class=\"kw-clinique\">sevrage</span>, <span class=\"kw-clinique\">craving</span>).\n      </div>\n      <p>Repère pratique pour le <span class=\"kw-def\">dépistage</span> du versant <strong>dépendance</strong> : le questionnaire <span class=\"kw-def\">AUDIT-C</span> oriente vers une alcoolodépendance probable à partir de <span class=\"kw-chiffre\">≥ 5</span> (homme) ou <span class=\"kw-chiffre\">≥ 4</span> (femme).</p>","frequence":3},{"id":"76-6","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir dépister un mésusage d’alcool : verres standards, consommation déclarée, AUDIT-C","contenu":"<p>Le <span class=\"kw-def\">dépistage</span> d’un <span class=\"kw-def\">mésusage</span> repose sur la quantification de la consommation et un autoquestionnaire validé.</p>\n      <p><strong>Quantifier la consommation :</strong></p>\n      <ul>\n        <li><strong>Méthode des verres :</strong> nombre de verres standard × <span class=\"kw-chiffre\">10 g</span>.</li>\n        <li><strong>Méthode précise :</strong> quantité (L) × 8 × degré d’<span class=\"kw-etio\">alcool</span> (ex. bouteille de 75 cl de vin à 12,5° = <span class=\"kw-chiffre\">75 g</span> d’<span class=\"kw-etio\">alcool</span> pur).</li>\n        <li><strong>Consommation déclarée d’<span class=\"kw-etio\">alcool</span> (CDA) :</strong> hebdomadaire ou quotidienne, en distinguant jours ouvrés / jours de repos et écarts / consommation habituelle.</li>\n        <li><strong>API</strong> (alcoolisation ponctuelle importante) = <span class=\"kw-chiffre\">≥ 6 verres standard en une occasion</span>.</li>\n      </ul>\n      <p><strong>Questionnaire <span class=\"kw-def\">AUDIT-C</span></strong> — 3 questions : fréquence de consommation ; nombre de verres un jour ordinaire ; fréquence des épisodes <span class=\"kw-chiffre\">≥ 6</span> verres.</p>\n      <table >\n        <thead><tr><th>Interprétation AUDIT-C</th><th>Homme</th><th>Femme</th></tr></thead>\n        <tbody>\n          <tr><td>Consommation à risque pour la santé</td><td><span class=\"kw-chiffre\">≥ 4</span></td><td><span class=\"kw-chiffre\">≥ 3</span></td></tr>\n          <tr><td>Alcoolodépendance probable</td><td><span class=\"kw-chiffre\">≥ 5</span></td><td><span class=\"kw-chiffre\">≥ 4</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Signes cliniques évocateurs d’un mésusage chronique :</strong> <span class=\"kw-clinique\">faciès vultueux</span>, <span class=\"kw-clinique\">couperose du visage</span>, parfois <span class=\"kw-clinique\">rhinophyma</span>.</p>","frequence":2},{"id":"76-7","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir rechercher et reconnaître les signes d’un syndrome de sevrage à l’alcool et les accidents de sevrage (convulsions et delirium tremens)","contenu":"<p>Le <span class=\"kw-def\">syndrome de sevrage</span> regroupe <span class=\"kw-clinique\">les</span> signes apparaissant lorsque l’alcoolémie décroît ou s’annule, chez un sujet dépendant. <strong><span class=\"kw-chiffre\">≥ 1</span>/3 des patients dépendants n’ont aucun symptôme</strong> de <span class=\"kw-ttt\">sevrage</span> à l’arrêt.</p>\n      <p><strong><span class=\"kw-def\">Physiopathologie</span> :</strong> l’<span class=\"kw-etio\">alcool</span> est <span class=\"kw-def\">agoniste des récepteurs GABA</span> (inhibiteurs) ; le <span class=\"kw-ttt\">sevrage</span> entraîne une <strong>baisse de la transmission GABAergique</strong> → <span class=\"kw-alerte\">hyperexcitabilité</span> neuronale.</p>\n      <table >\n        <thead><tr><th>Niveau de <span class=\"kw-ttt\">sevrage</span></th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td>Niveau 1</td><td>Hyperactivité neurovégétative (<span class=\"kw-clinique\">sueurs</span>, <span class=\"kw-clinique\">tachycardie</span>)</td></tr>\n          <tr><td>Niveau 2</td><td>Trouble de l’attention, <span class=\"kw-clinique\">hallucinations</span></td></tr>\n          <tr><td>Niveau 3</td><td><span class=\"kw-alerte\">Convulsions</span></td></tr>\n          <tr><td>Niveau 4</td><td><span class=\"kw-alerte\">Delirium tremens</span> — agitation majeure surajoutée</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Syndrome de <span class=\"kw-ttt\">sevrage</span> non compliqué :</strong></p>\n      <ul>\n        <li><strong>Délais :</strong> premiers symptômes <span class=\"kw-chiffre\">6 à 48 h</span> après l’arrêt (souvent le matin au réveil) ; maximum dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">72 premières heures</span> ; possibles jusqu’à <span class=\"kw-chiffre\">7-10 jours</span> ; régression en <span class=\"kw-chiffre\">2 à 5 jours</span> en l’absence de complication.</li>\n        <li><strong>Manifestations <span class=\"kw-clinique\">les</span> plus évocatrices :</strong> <span class=\"kw-clinique\">tremblements</span>, <span class=\"kw-clinique\">sueurs profuses</span>, <span class=\"kw-clinique\">anxiété</span>, <span class=\"kw-clinique\">vomissements</span>.</li>\n        <li><strong>Autres :</strong> psycho-comportementales (insomnie, cauchemars, irritabilité, agitation) ; neurovégétatives (<span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">HTA</span>) ; digestives (<span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">anorexie</span>, <span class=\"kw-clinique\">diarrhée</span>).</li>\n      </ul>\n      <p><strong>Accidents de <span class=\"kw-ttt\">sevrage</span> :</strong> en l’absence de prévention, le syndrome peut se compliquer d’une <span class=\"kw-clinique\">crise convulsive</span> (niveau 3) ou d’un <span class=\"kw-alerte\">delirium tremens</span> (niveau 4) — détaillés dans l’objectif « Savoir prendre en charge un accident de <span class=\"kw-ttt\">sevrage</span> ».</p>","frequence":0},{"id":"76-8","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir diagnostiquer une intoxication alcoolique aiguë avec ou sans coma éthylique (diagnostic différentiel) et rechercher les troubles métaboliques associés","contenu":"<p>L’<span class=\"kw-etio\">intoxication alcoolique aiguë</span> est la plus fréquente des intoxications aiguës ; son <strong>diagnostic est clinique</strong>. Il n’existe <strong>pas d’antidote</strong> — la prise en charge est purement symptomatique.</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Ivresse simple</span></td><td><strong>Phase d’excitation :</strong> agitation motrice ; logorrhée ; troubles de l’élocution ; haleine œnolique ; troubles de l’équilibre<br><strong>Phase hyporéactive :</strong> hyporéflexie ; hypoesthésie ; incontinence urinaire ; pouvant aller jusqu’au <span class=\"kw-clinique\">coma</span></td></tr>\n          <tr><td><span class=\"kw-def\">Ivresse pathologique</span></td><td>Plus rare : forme excito-motrice (agressivité, violences, actes clastiques) ; dépressive ; allure maniaque ; hallucinatoire ; délirante. Suivie d’un sommeil profond et d’une <span class=\"kw-clinique\">amnésie lacunaire</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Coma éthylique</span></td><td><strong><span class=\"kw-clinique\">Coma</span> calme :</strong> aréactivité ; <span class=\"kw-clinique\">mydriase</span> ; <span class=\"kw-clinique\">hypotonie</span> ; <span class=\"kw-alerte\">dépression respiratoire</span> ; <span class=\"kw-clinique\">hypothermie</span> ; <span class=\"kw-clinique\">hypotension</span> ; <strong>pas de signe de localisation</strong>. Peut engager le <span class=\"kw-alerte\">pronostic vital</span> → <span class=\"kw-alerte\">réanimation</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Troubles métaboliques à rechercher systématiquement.</strong> <span class=\"kw-bio\">Hypoglycémie</span> (enfant, alcoolique chronique dénutri) ; <span class=\"kw-bio\">acidocétose alcoolique</span> ; <span class=\"kw-bio\">hyponatrémie</span> (surtout gros buveur de bière) — <span class=\"kw-alerte\">à ne pas corriger trop vite</span> (risque de myélinolyse centropontine) ; <span class=\"kw-clinique\">hypothermie</span> ; <span class=\"kw-bio\">rhabdomyolyse</span>.\n      </div>\n      <p><strong>Paraclinique :</strong> aucun examen <span class=\"kw-ttt\">biologique</span> n’est nécessaire au diagnostic. L’<span class=\"kw-bio\">alcoolémie</span> n’est <strong>pas corrélée à la gravité clinique</strong> ; elle est réalisée en cas de tableau atypique ou de doute sur un <strong><span class=\"kw-def\">diagnostic différentiel</span></strong> (autre cause de <span class=\"kw-clinique\">coma</span>, traumatisme crânien, autre intoxication, hypoglycémie). <span class=\"kw-clinique\">Les</span> examens complémentaires servent à éliminer un diagnostic différentiel ou à chercher une complication.</p>\n      <p><strong>Prise en charge symptomatique :</strong> hydratation (NaCl <span class=\"kw-chiffre\">0,9 %</span>) ; <span class=\"kw-ttt\">benzodiazépine</span> si agitation ; apport vitaminique (<span class=\"kw-ttt\">B1</span>, <span class=\"kw-ttt\">B6</span>, <span class=\"kw-ttt\">PP</span>) si dénutrition / <span class=\"kw-etio\">alcoolisme</span> chronique ; protection des voies aériennes ; <span class=\"kw-def\">surveillance</span> horaire (conscience, <span class=\"kw-bio\">glycémie</span>, température). Au décours : intervention brève ou recours à l’ELSA.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 336 — <span class=\"kw-clinique\">Coma</span> non traumatique</em></p>","frequence":0},{"id":"76-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître l’association fréquente du mésusage d’alcool avec d’autres pathologies addictives et psychiatriques, qu’elles soient primaires ou secondaires","contenu":"<p>Le <span class=\"kw-def\">mésusage d’alcool</span> est fréquemment associé à d’autres troubles, qu’ils soient <strong>primaires</strong> (préexistants, parfois à l’origine de la consommation) ou <strong>secondaires</strong> (induits par l’<span class=\"kw-etio\">alcool</span>). Tout mésusage impose un <strong>bilan addictologique complet</strong>.</p>\n      <p><strong><span class=\"kw-def\">Comorbidités</span> addictives</strong> — à dépister systématiquement :</p>\n      <ul>\n        <li>Quantifier l’usage et rechercher <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">critères de</span> dépendance pour les <strong>autres substances psychoactives</strong>.</li>\n        <li>Rechercher <span class=\"kw-clinique\">les</span> <strong>addictions comportementales</strong>.</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Comorbidités</span> psychiatriques :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Troubles dépressifs</span> et <span class=\"kw-clinique\">troubles anxieux</span> : <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">comorbidités</span> les <strong>plus fréquentes</strong>.</li>\n        <li>Trouble psychotique induit par une substance ; aggravation de troubles psychiatriques préexistants.</li>\n        <li><span class=\"kw-alerte\">Conduites suicidaires</span> (risque fortement augmenté, surtout lors des intoxications aiguës).</li>\n        <li>Trouble de l’usage d’<span class=\"kw-etio\">alcool</span> chez <span class=\"kw-chiffre\">20-30 %</span> des patients schizophrènes et <span class=\"kw-chiffre\">40 %</span> des patients bipolaires.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction <span class=\"kw-etio\">Tabac</span> · 77 — Addiction aux psychotropes · 63 — Trouble schizophrénique · 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 66 — Trouble dépressif</em></p>","frequence":0},{"id":"76-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principales complications sociales du mésusage d’alcool et le lien avec la précarité","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong>complications sociales et socio-professionnelles</strong> du mésusage d’<span class=\"kw-etio\">alcool</span> sont <strong>quasi systématiques</strong> et touchent de nombreux domaines.</p>\n      <table >\n        <thead><tr><th>Domaine</th><th>Retentissement</th></tr></thead>\n        <tbody>\n          <tr><td>Familial</td><td><span class=\"kw-alerte\">Violences intrafamiliales</span> (psychologiques ou physiques) ; séparations ; <span class=\"kw-alerte\">mise en danger de l’enfance</span></td></tr>\n          <tr><td>Professionnel</td><td>Avertissement ; licenciement ; absentéisme ; chômage</td></tr>\n          <tr><td>Financier</td><td>Dettes ; négligence des obl<span class=\"kw-chiffre\">iga</span>tions administratives ; problème de logement</td></tr>\n          <tr><td>Judiciaire</td><td>Conduite en état d’ivresse ; ivresse publique manifeste ; violences ou délits sous l’effet de l’<span class=\"kw-etio\">alcool</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Lien avec la précarité.</strong> <span class=\"kw-clinique\">Les</span> troubles liés à l’usage d’<span class=\"kw-etio\">alcool</span> sont un <span class=\"kw-etio\">facteur de risque de précarité</span> ; réciproquement, la <span class=\"kw-etio\">précarité favorise la rechute</span> — c’est un cercle vicieux à repérer dans la prise en charge.\n      </div>","frequence":0},{"id":"76-11","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les marqueurs biologiques usuels de consommation d’alcool : alcoolémie, GGT, volume globulaire moyen (VGM), transferrine désialysée","contenu":"<p><span class=\"kw-clinique\">Les</span> examens biologiques <strong>n’établissent pas le diagnostic de dépendance</strong>. Ils servent à objectiver un mésusage et dépister ses complications (déni / minimisation), à suivre la pathologie (rechute), à des fins motivationnelles et dans le cadre médico-réglementaire.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Un <span class=\"kw-bio\">bilan biologique normal n’élimine pas</span> une consommation à risque.\n      </div>\n      <table >\n        <thead><tr><th>Marqueur</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Alcoolémie</span></td><td>Reflet de la consommation récente. Repères médico-légaux : contravention si <span class=\"kw-chiffre\">&gt; 0,5 g/L</span> dans le sang (ou <span class=\"kw-chiffre\">&gt; 0,25 mg/L</span> dans l’<span class=\"kw-def\">air</span> expiré) ; délit si <span class=\"kw-chiffre\">&gt; 0,8 g/L</span> (ou <span class=\"kw-chiffre\">&gt; 0,4 mg/L</span>)</td></tr>\n          <tr><td><span class=\"kw-bio\">GGT</span></td><td>Marqueur de consommation et de souffrance hépatique. Sensibilité et spécificité <strong>médiocres</strong> ; baisse dès la 1ʳᵉ semaine d’arrêt, normalisation en <span class=\"kw-chiffre\">4 à 10 semaines</span></td></tr>\n          <tr><td><span class=\"kw-bio\">VGM</span></td><td>Marqueur le <strong>moins sensible</strong> mais assez spécifique ; normalisation <strong>lente</strong> (≈ <span class=\"kw-chiffre\">3 mois</span> après l’arrêt)</td></tr>\n          <tr><td><span class=\"kw-bio\">CDT</span> (<span class=\"kw-bio\">transferrine</span> désialylée)</td><td>Très <strong>spécifique</strong>, meilleure sensibilité ; normalisation en <span class=\"kw-chiffre\">2 à 5 semaines</span>. Bon marqueur de <strong>rechute</strong> ; onéreux, surtout utilisé en cadre médico-réglementaire ou en cas de banalisation / déni</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"76-12","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les complications médicales générales principales de la consommation d’alcool","contenu":"<p><strong>Objectif majeur de l’item.</strong> La consommation chronique d’<span class=\"kw-etio\">alcool</span> retentit sur <strong>tous <span class=\"kw-clinique\">les</span> appareils</strong>. La prévention passe par une supplémentation vitaminique systématique de tout patient alcoolique hospitalisé.</p>\n      <p><strong>1 · <span class=\"kw-etio\">Alcool</span> et cancer.</strong> L’<span class=\"kw-etio\">alcool</span> est la <span class=\"kw-alerte\">2ᵉ cause de mortalité évitable par cancer</span>. Le risque augmente de façon <strong>linéaire avec la dose, sans seuil</strong> (même une consommation faible augmente le risque) ; <strong>synergie avec le <span class=\"kw-etio\">tabac</span></strong> pour <span class=\"kw-clinique\">les</span> cancers des VADS.</p>\n      <ul>\n        <li><strong>Localisations à risque fort :</strong> VADS (bouche, pharynx, larynx) ; œsophage (<span class=\"kw-clinique\">carcinome</span> épidermoïde) ; foie (carcinome hépatocellulaire).</li>\n        <li><strong>Autres localisations :</strong> estomac ; sein ; côlon-rectum.</li>\n      </ul>\n      <p><strong>2 · Atteintes des autres organes :</strong></p>\n      <table >\n        <thead><tr><th>Appareil</th><th>Complications</th></tr></thead>\n        <tbody>\n          <tr><td>Cardiovasculaire</td><td><span class=\"kw-clinique\">HTA</span> ; <span class=\"kw-alerte\">troubles du rythme</span> ; cardiomyopathie dilatée non obstructive ; <span class=\"kw-etio\">insuffisance cardiaque</span> gauche</td></tr>\n          <tr><td>Hématologique</td><td><span class=\"kw-bio\">Macrocytose</span> ; anémie ; thrombopénie ; leucopénie (toxicité directe, hépatopathie, carences)</td></tr>\n          <tr><td>Métabolique</td><td><span class=\"kw-bio\">Hypoglycémie</span> ; acidocétose alcoolique ; dénutrition (risque de <span class=\"kw-clinique\">syndrome de renutrition</span>) ; <span class=\"kw-etio\">hypertriglycéridémie</span> ; hyperuricémie / goutte ; <span class=\"kw-bio\">hypokaliémie</span> ; <span class=\"kw-bio\">hyponatrémie</span></td></tr>\n          <tr><td>Rhumatologique et traumatique</td><td><span class=\"kw-etio\">Ostéoporose</span> ; ostéomalacie ; <span class=\"kw-clinique\">nécrose</span> de la tête fémorale ; fractures et traumatismes crâniens (chutes)</td></tr>\n          <tr><td>Dermatologique</td><td><span class=\"kw-alerte\">Aggravation d’un psoriasis</span> ; rhinophyma</td></tr>\n          <tr><td>Génitale</td><td>Dysfonctions sexuelles</td></tr>\n          <tr><td><span class=\"kw-etio\">Infectieux</span></td><td>Complications liées aux conduites à risque : <span class=\"kw-etio\">VHB</span> ; <span class=\"kw-etio\">VHC</span> ; VIH ; autres <span class=\"kw-clinique\">IST</span></td></tr>\n          <tr><td>Fœtus</td><td><span class=\"kw-alerte\">Syndrome d’alcoolisation fœtale</span> : retard de croissance ; dysmorphie craniofaciale ; retard mental — recommandation « zéro <span class=\"kw-etio\">alcool</span> » pendant la <span class=\"kw-ci\">grossesse</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>3 · Complications digestives :</strong></p>\n      <table >\n        <thead><tr><th>Organe</th><th>Atteintes</th></tr></thead>\n        <tbody>\n          <tr><td>Foie</td><td><span class=\"kw-etio\">Stéatose</span> (<span class=\"kw-clinique\">lésion</span> la plus précoce, réversible) ; <span class=\"kw-etio\">hépatite alcoolique aiguë</span> ; <span class=\"kw-etio\">cirrhose</span> (micronodulaire)</td></tr>\n          <tr><td>Pancréas</td><td><span class=\"kw-etio\">Pancréatite aiguë</span> ; <span class=\"kw-etio\">pancréatite chronique</span> calcifiante</td></tr>\n          <tr><td>Intestin</td><td><span class=\"kw-clinique\">Diarrhée</span> motrice et/ou par atteinte entérocytaire</td></tr>\n        </tbody>\n      </table>\n      <p><strong>4 · Complications neurologiques.</strong> Mécanismes : toxicité directe (récepteurs GABA et glutamate) et indirecte (carences vitaminiques, atteinte d’organes, traumatismes).</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Entités</th></tr></thead>\n        <tbody>\n          <tr><td>Encéphalopathies</td><td><span class=\"kw-etio\">Gayet-Wernicke</span> (carence en <span class=\"kw-ttt\">vitamine B1</span>) ; encéphalopathie pellagreuse (carence en <span class=\"kw-ttt\">vitamine PP</span>) ; <span class=\"kw-alerte\">encéphalopathie hépatique</span></td></tr>\n          <tr><td>Troubles cognitifs</td><td><span class=\"kw-etio\">Syndrome de Korsakoff</span> (amnésie antérograde, fausses reconnaissances, fabulations) ; maladie de <span class=\"kw-etio\">Marchiafava-Bignami</span> (démyélinisation du corps calleux)</td></tr>\n          <tr><td>Cervelet</td><td><span class=\"kw-clinique\">Atrophie cérébelleuse</span> (vermis) : ataxie statique et locomotrice</td></tr>\n          <tr><td>Nerfs périphériques</td><td><span class=\"kw-clinique\">Polyneuropathie longueur-dépendante</span> (2ᵉ cause après le <span class=\"kw-etio\">diabète</span>) ; neuropathie optique alcoolo-tabagique</td></tr>\n          <tr><td>Muscle</td><td>Myopathie aiguë (rhabdomyolyse) ; myopathie chronique (faiblesse proximale)</td></tr>\n          <tr><td>Autres</td><td><span class=\"kw-etio\">Épilepsie</span> tardive ; complications indirectes : myélinolyse centropontine ; <span class=\"kw-etio\">AVC</span> (<span class=\"kw-etio\">ischémique</span> ou <span class=\"kw-etio\">hémorragique</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Prévention systématique.</strong> Chez tout patient alcoolique hospitalisé (quelle qu’en soit la raison) : supplément vitaminique <span class=\"kw-ttt\">B1</span> + <span class=\"kw-ttt\">B6</span> + <span class=\"kw-ttt\">B12</span> + <span class=\"kw-ttt\">folates</span> + <span class=\"kw-ttt\">PP</span>. Ne jamais administrer de sérum glucosé sans vitamine B1 chez un alcoolique (risque de déclencher une encéphalopathie de Gayet-Wernicke).\n      </div>\n      <p><strong>Focus imagerie — encéphalopathie de Gayet-Wernicke.</strong> L’<span class=\"kw-imagerie\">IRM</span> cérébrale montre des <span class=\"kw-imagerie\">hypersignaux FLAIR des corps mamillaires</span>. Cliniquement : triade <span class=\"kw-clinique\">syndrome confusionnel</span> + <span class=\"kw-clinique\">syndrome cérébelleux statique</span> + <span class=\"kw-clinique\">signes oculomoteurs</span> (paralysie oculomotrice, nystagmus). Traitement : <span class=\"kw-ttt\">vitaminothérapie B1 à forte dose IV</span> (<span class=\"kw-chiffre\">1 g/jour</span>), à débuter avant <span class=\"kw-clinique\">les</span> résultats des examens complémentaires.</p>\n      <div class=\"figure-row\">\n        <figure class=\"obj-figure\">\n          <img src=\"../assets/images/76/irm-gayet-wernicke-1.png\" alt=\"IRM cérébrale montrant des hypersignaux FLAIR des corps mamillaires, encéphalopathie de Gayet-Wernicke\" loading=\"lazy\">\n          <figcaption><span class=\"kw-imagerie\">IRM</span> cérébrale — encéphalopathie de Gayet-Wernicke : hypersignaux des corps mamillaires, témoins d’une carence aiguë en vitamine B1. Source : fiche source EDN item 76 (sous-dossier Encéphalopathie de Gayet-Wernicke).</figcaption>\n        </figure>\n        <figure class=\"obj-figure\">\n          <img src=\"../assets/images/76/irm-gayet-wernicke-2.png\" alt=\"IRM cérébrale, seconde coupe, encéphalopathie de Gayet-Wernicke\" loading=\"lazy\">\n          <figcaption><span class=\"kw-imagerie\">IRM</span> cérébrale — encéphalopathie de Gayet-Wernicke : seconde coupe illustrant l’atteinte périventriculaire. Source : fiche source EDN item 76 (sous-dossier Encéphalopathie de Gayet-Wernicke).</figcaption>\n        </figure>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — <span class=\"kw-etio\">Cirrhose</span> · 358 — <span class=\"kw-etio\">Pancréatite aiguë</span> · 281 — <span class=\"kw-etio\">Pancréatite chronique</span> · 167 — Hépatites virales · 105 — Epilepsie · 96 — Neuropathie périphérique · 340 — <span class=\"kw-etio\">AVC</span> · 250 — Dénutrition</em></p>","frequence":6,"liens":[{"href":"https://www.cen-neurologie.fr/second-cycle/addiction-a-lalcool-complications-neurologiques-de-lalcoolisme","label":"Collège CEN — Complications neurologiques de l'alcoolisme"},{"href":"https://radiopaedia.org/articles/wernicke-korsakoff-syndrome-2","label":"Radiopaedia : Wernicke-Korsakoff syndrome"}]},{"id":"76-13","rang":"A","rubrique":"Définition","titre":"Connaître les principes de base de la prévention primaire du mésusage d’alcool","contenu":"<p>La <span class=\"kw-def\">prévention primaire</span> du mésusage d’<span class=\"kw-etio\">alcool</span> vise à <strong>éviter ou retarder la première consommation</strong> de substances psychoactives.</p>\n      <ul>\n        <li><strong>Objectif :</strong> empêcher l’entrée dans la consommation, ou en retarder l’âge de début.</li>\n        <li><strong>Outils :</strong> information et éducation des futurs usagers.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>À distinguer.</strong> La <span class=\"kw-def\">prévention primaire</span> (avant toute consommation) se distingue de la <strong><span class=\"kw-def\">prévention secondaire</span></strong> = repérage précoce et intervention brève (RPIB), qui s’adresse à un mésusage déjà installé.\n      </div>","frequence":0},{"id":"76-14","rang":"B","rubrique":"Prise en charge","titre":"Connaître le repérage précoce et intervention brève (RPIB) et son contenu","contenu":"<p>Le <span class=\"kw-def\">repérage précoce et intervention brève (RPIB)</span> est une action de <strong><span class=\"kw-def\">prévention secondaire</span></strong>, en deux temps.</p>\n      <ul>\n        <li><strong>1 · Repérage précoce :</strong> <span class=\"kw-def\">dépistage</span> d’un mésusage d’<span class=\"kw-etio\">alcool</span> (questionnaire <span class=\"kw-def\">FACE</span>).</li>\n        <li><strong>2 · Intervention brève :</strong> proposée en cas de mésusage <strong>sans dépendance</strong>.</li>\n      </ul>\n      <p>L’<strong>intervention brève</strong> est dispensée individuellement, en un temps court (<span class=\"kw-chiffre\">5 à 20 minutes</span>), répétable. En insistant à chaque étape sur le <strong><span class=\"kw-def\">libre choix du patient</span></strong>, elle comporte :</p>\n      <ul>\n        <li>Restitution des résultats de l’évaluation de la consommation et de son retentissement.</li>\n        <li>Définition d’un <span class=\"kw-def\">verre standard</span> et des repères de consommation à moindre risque.</li>\n        <li>Information sur <span class=\"kw-clinique\">les</span> risques personnels ou situationnels.</li>\n        <li>Échange sur <span class=\"kw-clinique\">les</span> avantages à diminuer la consommation.</li>\n        <li>Choix d’un objectif de consommation (si le patient est d’accord).</li>\n        <li>Présentation des méthodes de <span class=\"kw-ttt\">réduction</span> (à la demande).</li>\n        <li>Remise d’une documentation écrite et orientation vers <span class=\"kw-clinique\">les</span> structures spécialisées.</li>\n        <li>Proposition d’une <span class=\"kw-def\">réévaluation</span> lors d’un autre entretien.</li>\n      </ul>","frequence":1},{"id":"76-15","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge","contenu":"<p>La prise en charge de la dépendance alcoolique doit être <strong>globale, <span class=\"kw-def\">médico-psycho-sociale</span> et pluridisciplinaire</strong>.</p>\n      <table >\n        <thead><tr><th>Dimension</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td>Objectifs (définis par le patient, évolutifs)</td><td>Arrêt complet (le plus réaliste en cas de dépendance sévère) ; retour à un usage à faible risque ; <span class=\"kw-ttt\">réduction</span> des consommations dans une logique de <span class=\"kw-def\">réduction des risques</span></td></tr>\n          <tr><td>Stratégies</td><td>Arrêt complet et encadré (<span class=\"kw-ttt\">sevrage</span>) puis maintien ; ou diminution progressive jusqu’à un usage à faible risque / un arrêt</td></tr>\n          <tr><td>Orientation</td><td><span class=\"kw-ttt\">Sevrage</span> ambulatoire (<span class=\"kw-chiffre\">80 %</span>) ou hospitalier (<span class=\"kw-chiffre\">20 %</span>) selon des indications alcoologiques, somatiques, psychiatriques et socio-environnementales</td></tr>\n          <tr><td>Moyens</td><td><span class=\"kw-def\">Entretien motivationnel</span> (central) ; soutien psychologique et <span class=\"kw-def\">TCC</span> ; <span class=\"kw-def\">groupes d’entraide</span> ; traitements pharmacologiques en <span class=\"kw-bio\">complément</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"76-16","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de l’entretien motivationnel","contenu":"<p>Le travail sur la <strong>motivation</strong> est <strong>central et indispensable</strong> dans la prise en charge des conduites addictives.</p>\n      <p>L’<span class=\"kw-def\">entretien motivationnel</span> est un <strong>style d’entretien collaboratif et participatif</strong>, centré sur la personne, qui vise à :</p>\n      <ul>\n        <li>Renforcer la <strong>motivation propre (<span class=\"kw-def\">intrinsèque</span>)</strong> au changement et l’engagement vers celui-ci.</li>\n        <li>Renforcer l’<strong>adhésion à la prise en charge</strong>.</li>\n        <li>Explorer et <strong>résoudre l’<span class=\"kw-def\">ambivalence</span></strong> du patient (statu quo entre rester dans le « comportement problème » et changer).</li>\n      </ul>\n      <p><strong>Esprit de l’entretien :</strong> il ne s’agit <strong>pas de convaincre</strong> le patient (motivation <span class=\"kw-def\">extrinsèque</span> imposée par le soignant) mais d’explorer <strong>avec lui</strong>, de façon <strong><span class=\"kw-def\">empathique</span> et sans jugement</strong>, <span class=\"kw-clinique\">les</span> avantages et inconvénients de chaque comportement. Le partenariat <strong>préserve le sentiment d’<span class=\"kw-def\">autonomie</span> et de liberté</strong> du patient (une résistance naît de la <span class=\"kw-alerte\">menace</span> de perte d’<span class=\"kw-def\">autonomie</span>). On <strong>valorise toute action en faveur du changement</strong>, même mineure, pour renforcer le sentiment d’<span class=\"kw-def\">efficacité personnelle</span>.</p>\n      <p><strong>Principes pratiques — acronyme <span class=\"kw-def\">VICTOIRE</span> :</strong></p>\n      <table >\n        <thead><tr><th>Principe</th><th>Mise en œuvre</th></tr></thead>\n        <tbody>\n          <tr><td><strong>V</strong>aloriser</td><td>Valoriser toute action, même mineure, en faveur du changement.</td></tr>\n          <tr><td><strong>I</strong>ntéresser</td><td>Susciter l’intérêt du patient sur la question du changement et son <span class=\"kw-def\">ambivalence</span>.</td></tr>\n          <tr><td><strong>C</strong>omprendre</td><td>Montrer une démarche <span class=\"kw-def\">empathique</span> de compréhension.</td></tr>\n          <tr><td><strong>T</strong>olérer</td><td>Tolérer <span class=\"kw-clinique\">les</span> résistances, avec un jugement positif inconditionnel ; laisser le patient exprimer ses arguments.</td></tr>\n          <tr><td><strong>O</strong>uvrir</td><td>Favoriser <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">questions ouvertes</span> (réponses personnelles et nuancées).</td></tr>\n          <tr><td><strong>I</strong>nsister</td><td>Insister sur l’<span class=\"kw-def\">ambivalence</span> sans prendre parti ni argumenter contre <span class=\"kw-clinique\">les</span> représentations du patient.</td></tr>\n          <tr><td><strong>R</strong>eformuler</td><td>Reprendre le discours du patient (<span class=\"kw-def\">empathie</span>).</td></tr>\n          <tr><td><strong>É</strong>couter</td><td>Se laisser informer par le patient sur ses propres représentations.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Stades du changement (<span class=\"kw-def\">Prochaska</span> &amp; DiClemente).</strong> La motivation n’est <strong>pas un trait de caractère immuable</strong> mais un état fluctuant. 6 étapes : <strong><span class=\"kw-def\">pré-contemplation</span></strong> → <strong>contemplation</strong> → <strong><span class=\"kw-def\">détermination</span></strong> → <strong>action</strong> → <strong>maintien</strong> → <strong>rechute</strong> (qui peut relancer le cycle, sans induire de sentiment d’échec).\n      </div>","frequence":1},{"id":"76-17","rang":"B","rubrique":"Prise en charge","titre":"Savoir prendre en charge un sevrage encadré d’alcool","contenu":"<p>Le <strong><span class=\"kw-ttt\">sevrage</span> encadré</strong> est proposé au patient alcoolodépendant qui souhaite arrêter sa consommation ; il est idéalement <strong>planifié</strong> et intégré à une prise en charge globale, parfois <strong>contraint</strong> (<span class=\"kw-alerte\">hospitalisation</span> pour une autre pathologie).</p>\n      <p>L’évaluation de la sévérité utilise le <span class=\"kw-def\">score de Cushman</span> (7 items : pouls, PAS, FR, tremblement, sueur, agitation, troubles sensoriels) :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Score</span> de Cushman</th><th>Sévérité du <span class=\"kw-ttt\">sevrage</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">0 à 7</span></td><td><span class=\"kw-ttt\">Sevrage</span> léger / minimal</td></tr>\n          <tr><td><span class=\"kw-chiffre\">8 à 14</span></td><td><span class=\"kw-ttt\">Sevrage</span> modéré</td></tr>\n          <tr><td><span class=\"kw-chiffre\">15 à 21</span></td><td><span class=\"kw-ttt\">Sevrage</span> sévère</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Orientation :</strong> le <span class=\"kw-ttt\">sevrage</span> <strong>ambulatoire</strong> est à préférer en l’absence de <span class=\"kw-ci\">contre-indication</span> (encadré par le médecin généraliste ou une équipe spécialisée — CSAPA). Indications du <strong><span class=\"kw-ttt\">sevrage</span> hospitalier</strong> :</p>\n      <ul>\n        <li>Demande du patient ; <span class=\"kw-alerte\">antécédent d’accident de sevrage</span> (<span class=\"kw-clinique\">crise convulsive</span>, delirium tremens).</li>\n        <li>Dépendance sévère ; <span class=\"kw-def\">comorbidité</span> addictive non stabilisée.</li>\n        <li>Échecs répétés de sevrages ambulatoires.</li>\n        <li>Environnement social défavorable (précarité) ; <span class=\"kw-def\">terrain</span> vulnérable (pathologie sévère, femme enceinte, personne âgée).</li>\n      </ul>\n      <p><strong>Modalités :</strong> arrêt complet de l’<span class=\"kw-etio\">alcool</span>, avec prévention des manifestations neurologiques :</p>\n      <ul>\n        <li><strong>Hydratation</strong> orale adaptée (<span class=\"kw-chiffre\">2 à 3 L/24 h</span>).</li>\n        <li><strong>Vitaminothérapie</strong> <span class=\"kw-ttt\">B1</span> / <span class=\"kw-ttt\">B6</span> per os (parentérale si suspicion de Gayet-Wernicke).</li>\n        <li><span class=\"kw-ttt\">Benzodiazépine à demi-vie longue</span> : <span class=\"kw-ttt\">diazépam</span> à doses progressivement décroissantes sur <span class=\"kw-chiffre\">7 à 10 jours</span> maximum (<span class=\"kw-ci\">prudence si insuffisance hépatique ou personne âgée</span>).</li>\n      </ul>","frequence":0},{"id":"76-18","rang":"B","rubrique":"Prise en charge","titre":"Savoir prendre en charge un accident de sevrage (crise convulsive ou delirium tremens)","contenu":"<p>En l’absence de prévention, le syndrome de <span class=\"kw-ttt\">sevrage</span> peut se compliquer d’une <strong><span class=\"kw-clinique\">crise convulsive</span></strong> ou d’un <strong>delirium tremens</strong> — deux urgences.</p>\n      <p><strong><span class=\"kw-clinique\">Crise convulsive</span> de <span class=\"kw-ttt\">sevrage</span></strong> (niveau 3) :</p>\n      <ul>\n        <li><span class=\"kw-def\">Terrain</span> : patient encore <strong>jeune</strong> ; crise <span class=\"kw-clinique\">généralisée tonicoclonique</span>, le plus souvent <strong>unique</strong> ; survient dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">12 à 48 h</span> du <span class=\"kw-ttt\">sevrage</span> ; <span class=\"kw-alerte\">état de mal</span> dans <span class=\"kw-chiffre\">5 %</span> des cas.</li>\n        <li><span class=\"kw-imagerie\">EEG</span> le plus souvent normal ; imagerie cérébrale justifiée lors d’une 1ʳᵉ crise.</li>\n        <li><strong>Pas de traitement antiépileptique au long cours</strong> ; <span class=\"kw-ttt\">benzodiazépines</span> ponctuelles pour réduire <span class=\"kw-clinique\">les</span> autres symptômes de <span class=\"kw-ttt\">sevrage</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong>Delirium tremens — <span class=\"kw-alerte\">urgence</span> vitale</strong> (niveau 4). <strong>Pré-delirium tremens</strong> (signes de début) : inversion du rythme nycthéméral, cauchemars, irritabilité, anxiété, <span class=\"kw-clinique\">sueurs</span>, tremblement postural → prise en charge urgente (hydratation + vitamines + <span class=\"kw-ttt\">benzodiazépines</span>) pour éviter l’<span class=\"kw-clinique\">évolution</span>.<br>\n        <strong>DT avéré :</strong> syndrome confuso-onirique (<span class=\"kw-clinique\">hallucinations</span> visuelles, <span class=\"kw-clinique\">zoopsies</span>, scènes d’agression, agitation) + syndrome physique (<span class=\"kw-alerte\">fièvre</span>, <span class=\"kw-clinique\">sueurs</span>, <span class=\"kw-clinique\">tachycardie</span>, troubles du rythme).\n      </div>\n      <p><strong>Traitement du delirium tremens :</strong></p>\n      <table >\n        <thead><tr><th>Mesure</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Hydratation</strong></td><td>Adaptée au bilan électrolytique (répété) ; <span class=\"kw-def\">surveillance</span> de la diurèse.</td></tr>\n          <tr><td><strong>Vitaminothérapie</strong></td><td><span class=\"kw-ttt\">B1</span> + <span class=\"kw-ttt\">B6</span> + <span class=\"kw-ttt\">PP</span>.</td></tr>\n          <tr><td><span class=\"kw-ttt\">Benzodiazépines IV</span></td><td>Dose de charge par <span class=\"kw-ttt\">diazépam</span> ; privilégier le <span class=\"kw-ttt\">lorazépam</span> si <span class=\"kw-alerte\">insuffisance hépatocellulaire</span> (métabolisme par conjugaison). Disposer de moyens de <span class=\"kw-alerte\">réanimation</span> et de l’antidote (<span class=\"kw-ttt\">flumazénil</span>).</td></tr>\n          <tr><td><strong>Corrections métaboliques</strong></td><td>Correction de l’<span class=\"kw-bio\">hypokaliémie</span> et de l’<span class=\"kw-clinique\">hyperthermie</span> ; traitement des facteurs favorisants (infection, traumatisme).</td></tr>\n          <tr><td><span class=\"kw-ttt\">Neuroleptiques</span> (recours)</td><td>En recours prudent, uniquement si <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">hallucinations</span> persistent malgré les <span class=\"kw-ttt\">benzodiazépines</span>.</td></tr>\n        </tbody>\n      </table>","frequence":4},{"id":"76-19","rang":"B","rubrique":"Prise en charge","titre":"Connaître l’existence des groupes d’entraide et des structures de soins en addictologie","contenu":"<p>La prise en charge addictologique s’appuie sur des <strong><span class=\"kw-def\">groupes d’entraide</span></strong> et des <strong>structures de soins spécialisées</strong>.</p>\n      <table >\n        <thead><tr><th>Ressource</th><th>Exemples / rôle</th></tr></thead>\n        <tbody>\n          <tr><td>Groupes d’entraide</td><td><span class=\"kw-def\">Vie Libre</span> ; <span class=\"kw-def\">Alcooliques Anonymes</span> ; <span class=\"kw-etio\">Alcool</span> Assistance</td></tr>\n          <tr><td><span class=\"kw-def\">CSAPA</span></td><td>Centre de soins, d’accompagnement et de prévention en addictologie — encadrement du <span class=\"kw-ttt\">sevrage</span> ambulatoire et <span class=\"kw-def\">suivi</span> spécialisé</td></tr>\n          <tr><td><span class=\"kw-def\">ELSA</span></td><td>Équipe de liaison et de soins en addictologie — intervient à l’hôpital pour orienter vers des soins spécialisés</td></tr>\n          <tr><td>Consultations hospitalières</td><td>Consultations d’addictologie hospitalières</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"76-20","rang":"B","rubrique":"Prise en charge","titre":"Connaître l’existence de médicaments spécifiques dans la dépendance à l’alcool","contenu":"<p><strong>Objectif très tombé.</strong> Des médicaments spécifiques complètent la prise en charge de la dépendance alcoolique, selon deux indications distinctes.</p>\n      <table >\n        <thead><tr><th>Indication</th><th>1ʳᵉ intention</th><th>2ᵉ intention</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Réduction</span> des consommations</strong></td>\n            <td><span class=\"kw-ttt\">Nalméfène</span> (Selincro®) — antagoniste opioïde, <span class=\"kw-ci\">CI avec les opiacés</span> ; prise ponctuelle ou continue ; pas d’effet secondaire grave mais mal toléré par ⅓ des patients</td>\n            <td><span class=\"kw-ttt\">Baclofène</span> (Liorésal®) — agoniste GABA-B ; titration progressive nécessaire ; nombreux effets secondaires bénins ou graves</td>\n          </tr>\n          <tr>\n            <td><strong>Maintien de l’abstinence après <span class=\"kw-ttt\">sevrage</span></strong></td>\n            <td><span class=\"kw-ttt\">Acamprosate</span> (Aotal®) — réduit le <em>craving</em> négatif ; bonne tolérance<br><span class=\"kw-ttt\">Naltrexone</span> (Revia®) — antagoniste opioïde, <span class=\"kw-ci\">CI avec les opiacés</span> ; réduit le <em>craving</em> positif</td>\n            <td><span class=\"kw-ttt\">Disulfirame</span> (Espéral®) — effet antabuse (flush, <span class=\"kw-clinique\">palpitations</span>, <span class=\"kw-clinique\">nausées</span>) ; <span class=\"kw-ci\">alcool formellement contre-indiqué dans les 3 jours suivant la prise</span><br><span class=\"kw-ttt\">Baclofène</span> (Liorésal®)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Mnémo.</strong> <span class=\"kw-clinique\">Les</span> molécules en « -fène » <strong>freinent la consommation</strong> (<span class=\"kw-ttt\">nalméfène</span>, <span class=\"kw-ttt\">baclofène</span>). Le <span class=\"kw-ttt\">disulfirame</span> expose à des complications graves en cas de prise d’<span class=\"kw-etio\">alcool</span> (troubles du rythme, collapsus, <span class=\"kw-clinique\">infarctus</span>, <span class=\"kw-alerte\">mort subite</span>).\n      </div>","frequence":5}],"astuces":[],"strategie":{"urgence":"<p><strong>Delirium tremens :</strong> <span class=\"kw-alerte\">urgence médicale</span> — <span class=\"kw-ttt\">benzodiazépines</span> + <span class=\"kw-ttt\">réhydratation</span> + <span class=\"kw-def\">surveillance</span> immédiates<br><strong><span class=\"kw-alerte\">Coma</span> éthylique :</strong> <span class=\"kw-alerte\">signes de gravité</span> (<span class=\"kw-alerte\">dépression respiratoire</span>, <span class=\"kw-clinique\">hypothermie</span>, <span class=\"kw-clinique\">hypotension</span>) → <span class=\"kw-alerte\">pronostic vital engagé</span>, transfert en <span class=\"kw-ttt\">réanimation</span><br><strong>Délais du <span class=\"kw-ttt\">sevrage</span> :</strong> premiers signes <span class=\"kw-chiffre\">6 à 48 h</span> après l'arrêt, maximum dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">72 h</span>, jusqu'à <span class=\"kw-chiffre\">7-10 jours</span><br><strong>Crise convulsive de <span class=\"kw-ttt\">sevrage</span> :</strong> survient dans les <span class=\"kw-chiffre\">12 à 48 h</span> suivant l'arrêt<br><strong>1er geste (intoxication aiguë) :</strong> <span class=\"kw-ttt\">hydratation IV (NaCl 0,9 %)</span> + surveillance <span class=\"kw-bio\">glycémique</span> (<span class=\"kw-alerte\">hypoglycémie</span> +++) et neurologique</p>","hospit":"<p><strong>Par défaut :</strong> <span class=\"kw-ttt\">sevrage ambulatoire</span> (≈ <span class=\"kw-chiffre\">80 %</span>), encadré par le médecin généraliste ou une équipe addictologique (<span class=\"kw-def\">CSAPA</span>)<br><strong><span class=\"kw-ttt\">Sevrage</span> hospitalier</strong> (≈ <span class=\"kw-chiffre\">20 %</span>) si : <span class=\"kw-alerte\">ATCD de delirium tremens</span> ou de crise convulsive, dépendance sévère, échecs répétés de <span class=\"kw-ttt\">sevrage</span> ambulatoire<br><strong>Hospitalier aussi si :</strong> <span class=\"kw-def\">comorbidité</span> psychiatrique ou addictive sévère, terrain vulnérable (<span class=\"kw-clinique\">femme enceinte</span>, sujet âgé), environnement social défavorable (<span class=\"kw-etio\">précarité</span>), demande du patient<br><strong>Intoxication aiguë :</strong> unité d'<span class=\"kw-alerte\">hospitalisation</span> de très courte durée (UHCD) ; au décours, intervention brève ou orientation par l'<span class=\"kw-def\">ELSA</span></p>","redflags":"<ul><li><span class=\"kw-alerte\">Coma</span> éthylique : <span class=\"kw-clinique\">aréactivité</span>, <span class=\"kw-clinique\">mydriase</span>, <span class=\"kw-alerte\">dépression respiratoire</span>, <span class=\"kw-clinique\">hypothermie</span>, <span class=\"kw-clinique\">hypotension</span></li><li><span class=\"kw-alerte\">Delirium tremens</span> : syndrome confuso-onirique, <span class=\"kw-clinique\">hallucinations</span> visuelles (<span class=\"kw-clinique\">zoopsies</span>), <span class=\"kw-clinique\">agitation</span> majeure, <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">tachycardie</span>, troubles du rythme</li><li><span class=\"kw-alerte\">État de mal épileptique</span> (jusqu'à <span class=\"kw-chiffre\">5 %</span> des crises de <span class=\"kw-ttt\">sevrage</span>)</li><li>Pré-delirium tremens (signes de début) : inversion du rythme nycthéméral, cauchemars, irritabilité, <span class=\"kw-clinique\">sueurs</span>, <span class=\"kw-clinique\">tremblements</span></li><li>Troubles métaboliques : <span class=\"kw-alerte\">hypoglycémie</span>, <span class=\"kw-etio\">acidocétose alcoolique</span>, <span class=\"kw-bio\">hyponatrémie</span> (risque de <span class=\"kw-alerte\">myélinolyse centropontine</span> si correction trop rapide), <span class=\"kw-bio\">hypokaliémie</span> (troubles du rythme)</li><li><span class=\"kw-def\">Score</span> de Cushman <span class=\"kw-chiffre\">≥ 15</span> = <span class=\"kw-ttt\">sevrage</span> sévère → <span class=\"kw-def\">surveillance</span> accrue et <span class=\"kw-alerte\">hospitalisation</span></li></ul>","principes":"<p>Prise en charge globale, <span class=\"kw-def\">médico-psycho-sociale et pluridisciplinaire</span>, fondée sur le <span class=\"kw-def\">travail motivationnel</span> ; l'objectif (arrêt complet, retour à un usage à faible risque ou <span class=\"kw-ttt\">réduction</span>) est défini par le patient.</p><p><strong><span class=\"kw-ttt\">Sevrage</span> encadré — modalités</strong></p><p><span class=\"kw-ci\">Éviter les BZD à demi-vie longue</span> en cas d'<span class=\"kw-ci\">insuffisance hépatique</span> ou chez le sujet âgé (<span class=\"kw-ttt\">sevrage</span> alors hospitalier, BZD seulement si signes de <span class=\"kw-ttt\">sevrage</span>)</p><ul><li><span class=\"kw-ttt\">Hydratation orale</span> adaptée (<span class=\"kw-chiffre\">2 à 3 L / 24 h</span>)</li><li><span class=\"kw-ttt\">Vitaminothérapie B1 / B6</span> per os (<span class=\"kw-ttt\">parentérale</span> si suspicion d'<span class=\"kw-etio\">encéphalopathie de Gayet-Wernicke</span>)</li><li><span class=\"kw-ttt\">Diazépam</span> (BZD à demi-vie longue) à doses progressivement décroissantes sur <span class=\"kw-chiffre\">7 à 10 jours</span> maximum</li></ul><p><strong>Accident de <span class=\"kw-ttt\">sevrage</span> — crise convulsive</strong></p><ul><li><span class=\"kw-ttt\">Benzodiazépines</span> ponctuelles pour réduire <span class=\"kw-clinique\">les</span> autres symptômes de <span class=\"kw-ttt\">sevrage</span></li><li><span class=\"kw-ci\">Pas de traitement antiépileptique au long cours</span> (crise généralement unique)</li><li><span class=\"kw-imagerie\">Imagerie cérébrale</span> justifiée lors d'une 1re crise (<span class=\"kw-clinique\">lésion</span> associée)</li></ul><p><strong>Accident de <span class=\"kw-ttt\">sevrage</span> — delirium tremens</strong></p><p>Corriger l'<span class=\"kw-bio\">hypokaliémie</span> et l'<span class=\"kw-clinique\">hyperthermie</span>, traiter <span class=\"kw-clinique\">les</span> facteurs favorisants (infection pulmonaire, traumatisme)</p><ul><li><span class=\"kw-ttt\">Réhydratation</span> adaptée au bilan électrolytique répété + <span class=\"kw-def\">surveillance</span> de la diurèse</li><li><span class=\"kw-ttt\">Vitamines B1 + B6 + PP</span></li><li><span class=\"kw-ttt\">Diazépam IV</span> en dose de charge (<span class=\"kw-chiffre\">10 mg/h</span>), moyens de <span class=\"kw-alerte\">réanimation</span> et antidote (<span class=\"kw-ttt\">flumazénil</span>) disponibles</li><li><span class=\"kw-ttt\">Lorazépam</span> si <span class=\"kw-alerte\">insuffisance hépatocellulaire</span> ; <span class=\"kw-ttt\">neuroleptiques</span> seulement si hallucinations persistantes</li></ul><p><strong>Médicaments — <span class=\"kw-ttt\">réduction</span> des consommations</strong></p><ul><li>1re intention : <span class=\"kw-ttt\">nalméfène</span> (antagoniste opioïde, <span class=\"kw-ci\">CI avec les opiacés</span>)</li><li><span class=\"kw-chiffre\">2e intention</span> : <span class=\"kw-ttt\">baclofène</span> (agoniste GABA-B, titration progressive)</li></ul><p><strong>Médicaments — maintien de l'abstinence après <span class=\"kw-ttt\">sevrage</span></strong></p><ul><li>1re intention : <span class=\"kw-ttt\">acamprosate</span> (réduit le craving négatif) et <span class=\"kw-ttt\">naltrexone</span> (réduit le craving positif, <span class=\"kw-ci\">CI avec les opiacés</span>)</li><li><span class=\"kw-chiffre\">2e intention</span> : <span class=\"kw-ttt\">disulfirame</span> (effet antabuse — <span class=\"kw-etio\">alcool</span> <span class=\"kw-ci\">formellement contre-indiqué dans les 3 jours suivant la prise</span>), <span class=\"kw-ttt\">baclofène</span></li></ul><p><strong>Approches non médicamenteuses</strong></p><ul><li><span class=\"kw-def\">Entretien motivationnel</span> (renforcer la motivation au changement)</li><li><span class=\"kw-def\">Thérapies cognitivo-comportementales (TCC)</span> et soutien psychocomportemental</li><li>Groupes d'entraide (Vie Libre, Alcooliques Anonymes, <span class=\"kw-etio\">Alcool</span> Assistance)</li><li><span class=\"kw-def\">RPIB</span> (repérage précoce et intervention brève) en cas de mésusage sans dépendance</li></ul>","suivi":"<p><strong>Sévérité du <span class=\"kw-ttt\">sevrage</span> :</strong> <span class=\"kw-def\">score de Cushman</span> (pouls, PAS, FR, tremblement, sueur, agitation, troubles sensoriels) — <span class=\"kw-chiffre\">0-7</span> léger, <span class=\"kw-chiffre\">8-14</span> modéré, <span class=\"kw-chiffre\">≥ 15</span> sévère<br><strong>Intoxication aiguë :</strong> <span class=\"kw-def\">surveillance</span> horaire des constantes, conscience (<span class=\"kw-clinique\">Glasgow</span>), <span class=\"kw-bio\">glycémie</span>, température, protection des voies aériennes<br><strong>Delirium tremens :</strong> surveillance cardiorespiratoire, diurèse, bilan électrolytique répété<br><strong>Marqueurs biologiques de <span class=\"kw-def\">suivi</span> / rechute :</strong> <span class=\"kw-bio\">GGT</span> (normalise en <span class=\"kw-chiffre\">4-10 sem</span>), <span class=\"kw-bio\">VGM</span> (<span class=\"kw-chiffre\">3 mois</span>), <span class=\"kw-bio\">CDT</span> (<span class=\"kw-bio\">transferrine</span> désialylée, <span class=\"kw-chiffre\">2-5 sem</span>, marqueur de rechute)</p>"},"liensGlobaux":[{"href":"https://www.cen-neurologie.fr/second-cycle/addiction-a-lalcool-complications-neurologiques-de-lalcoolisme","label":"cen-neurologie.fr"},{"href":"https://radiopaedia.org/articles/wernicke-korsakoff-syndrome-2","label":"radiopaedia.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Patient alcoolo-dépendant — sevrage — Programmé en ambulatoire par défaut, ou contraint lors d'une hospitalisation","detail":"<h4>CAT — <span class=\"kw-ttt\">Sevrage</span> alcoolique et accidents de <span class=\"kw-ttt\">sevrage</span> — Orientation ambulatoire/hospitalière puis conduite devant un accident de sevrage</h4>","branches":[{"to":"q-orient","label":"Évaluer l'orientation","color":"blue"}]},{"id":"q-orient","kind":"decision","label":"Indication de sevrage hospitalier ? — ATCD de delirium tremens / crise convulsive · dépendance sévère · échecs de sevrage ambulatoire · terrain vulnérable (femme enceinte, sujet âgé) · comorbidité psychiatrique ou addictive · précarité","branches":[{"to":"t-ambu","label":"Non","color":"green"},{"to":"q-accident","label":"Oui","color":"amber"}]},{"id":"t-ambu","kind":"terminal","label":"Sevrage AMBULATOIRE encadré — ≈ 80 % des sevrages","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Hydratation orale</span> <span class=\"kw-chiffre\">2-3 L/24 h</span> + <span class=\"kw-ttt\">vitaminothérapie B1/B6</span></li><li><span class=\"kw-ttt\">Diazépam</span> à doses décroissantes sur <span class=\"kw-chiffre\">7-10 jours</span> maximum</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Encadrement par le médecin généraliste ou une équipe addictologique (<span class=\"kw-def\">CSAPA</span>)</li><li><span class=\"kw-def\">Score de Cushman</span></li></ul>"},{"id":"q-accident","kind":"decision","label":"Accident de sevrage en cours ? — Apparition dans les 6 à 48 h suivant l'arrêt de la consommation","branches":[{"to":"t-hospit","label":"Non","color":"green"},{"to":"q-type","label":"Oui","color":"red"}]},{"id":"t-hospit","kind":"terminal","label":"Sevrage HOSPITALIER encadré — Sevrage non compliqué","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Hydratation</span> + <span class=\"kw-ttt\">vitaminothérapie B1/B6</span> (<span class=\"kw-ttt\">parentérale</span> si suspicion de <span class=\"kw-etio\">Gayet-Wernicke</span>)</li><li><span class=\"kw-ttt\">Diazépam</span> décroissant sur <span class=\"kw-chiffre\">7-10 jours</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Score de Cushman</span> et constantes répétées</li></ul>"},{"id":"q-type","kind":"decision","label":"Type d'accident de sevrage ?","branches":[{"to":"t-predt","label":"Signes de début (pré-DT)","color":"amber"},{"to":"t-convulsion","label":"Crise convulsive","color":"amber"},{"to":"t-dt","label":"Delirium tremens avéré","color":"red"}]},{"id":"t-predt","kind":"terminal","label":"Pré-delirium tremens (signes de début) — Prise en charge urgente pour prévenir l'évolution vers le DT","color":"amber","detail":"<h4>Clinique</h4><ul><li>Inversion du rythme nycthéméral, cauchemars, irritabilité, <span class=\"kw-clinique\">sueurs</span>, <span class=\"kw-clinique\">tremblements</span> posturaux</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Hydratation per os</span> + <span class=\"kw-ttt\">vitamines B1/B6/PP</span></li><li><span class=\"kw-ttt\">Benzodiazépines</span> (<span class=\"kw-ttt\">diazépam</span>, clonazépam) avec <span class=\"kw-def\">surveillance</span> cardiorespiratoire</li></ul>"},{"id":"t-convulsion","kind":"terminal","label":"Crise convulsive de sevrage — Niveau 3 · 12-48 h après l'arrêt","color":"amber","detail":"<h4>Clinique</h4><ul><li>Crise généralisée tonicoclonique, le plus souvent unique</li><li><span class=\"kw-alerte\">État de mal</span> dans <span class=\"kw-chiffre\">5 %</span> des cas</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Benzodiazépines</span> ponctuelles</li><li><span class=\"kw-ci\">Pas d'antiépileptique au long cours</span> ; <span class=\"kw-imagerie\">imagerie cérébrale</span> si 1re crise</li></ul>"},{"id":"t-dt","kind":"terminal","label":"Delirium tremens — urgence médicale — Niveau 4 · pronostic vital engagé","color":"red","detail":"<h4>Clinique</h4><ul><li>Syndrome confuso-onirique, <span class=\"kw-clinique\">hallucinations</span> visuelles (<span class=\"kw-clinique\">zoopsies</span>), <span class=\"kw-clinique\">agitation</span> majeure</li><li><span class=\"kw-clinique\">Fièvre</span>, <span class=\"kw-clinique\">tachycardie</span>, troubles du rythme</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Réhydratation</span> + <span class=\"kw-ttt\">vitamines B1/B6/PP</span></li><li><span class=\"kw-ttt\">Diazépam IV</span> en dose de charge (<span class=\"kw-chiffre\">10 mg/h</span>) + moyens de <span class=\"kw-alerte\">réanimation</span> et <span class=\"kw-ttt\">flumazénil</span></li><li><span class=\"kw-ttt\">Lorazépam</span> si <span class=\"kw-alerte\">insuffisance hépatocellulaire</span></li></ul><h4>Conduite</h4><ul><li>Correction de l'<span class=\"kw-bio\">hypokaliémie</span> et de l'<span class=\"kw-clinique\">hyperthermie</span></li><li><span class=\"kw-ttt\">Neuroleptiques</span> seulement si hallucinations persistantes malgré <span class=\"kw-clinique\">les</span> BZD</li></ul>"}]},"cards":[{"i":"3636675c0a18","n":76,"o":"76-1","u":"Épidémiologie","t":"Connaître les principaux chiffres liés à la consommation d’alcool en France (sources BEH 2019)","q":"Quelle est la fréquence des ivresses dans l'année et du dépassement des repères de l'usage à faible risque d'alcool en France ?","a":"<p>En France, <strong>1 adulte sur 5</strong> a été en état d'ivresse dans l'année, et <strong>au moins 1 adulte sur 5</strong> dépasse les repères de l'usage à faible risque d'alcool.</p>"},{"i":"5b88c1363357","n":76,"o":"76-1","u":"Épidémiologie","t":"Connaître les principaux chiffres liés à la consommation d’alcool en France (sources BEH 2019)","q":"Quel est le pourcentage d'hospitalisations directement causées par l'alcoolisme en France, et quelle est la proportion de patients souffrant de troubles liés à l'usage d'alcool qui accèdent aux soins spécialisés ?","a":"<p>L'alcoolisme est la cause directe de <strong>15 à 25 % des hospitalisations</strong> en France. Cependant, <strong>à peine 10 %</strong> des patients souffrant de troubles liés à l'usage d'alcool accèdent à des soins spécialisés.</p>"},{"i":"6285031e3194","n":76,"o":"76-1","u":"Épidémiologie","t":"Connaître les principaux chiffres liés à la consommation d’alcool en France (sources BEH 2019)","q":"Quel est l'impact de l'alcool sur la mortalité en France et chez les jeunes adultes ?","a":"<p>L'alcool est la <strong>deuxième cause de mortalité évitable</strong> en France, après le tabagisme, responsable d'environ <strong>41 000 décès par an</strong>. Chez les 20-39 ans, la part de mortalité évitable attribuable à l'alcool est particulièrement élevée, atteignant <strong>25 %</strong>.</p>"},{"i":"6e40a8e6ca0e","n":76,"o":"76-1","u":"Épidémiologie","t":"Connaître les principaux chiffres liés à la consommation d’alcool en France (sources BEH 2019)","q":"Quelles sont les tranches d'âge les plus concernées par les consommations régulières d'alcool et les alcoolisations ponctuelles importantes ?","a":"<p>Les <strong>consommations régulières</strong> d'alcool concernent plus particulièrement les personnes de <strong>65 ans et plus</strong>. Les <strong>alcoolisations ponctuelles importantes (API)</strong> et les ivresses ponctuelles sont surtout observées chez les <strong>jeunes adultes</strong>.</p>"},{"i":"860df833a912","n":76,"o":"76-1","u":"Épidémiologie","t":"Connaître les principaux chiffres liés à la consommation d’alcool en France (sources BEH 2019)","q":"Quelle est la proportion d'adultes ayant une consommation quotidienne d'alcool en France, et quel est le déséquilibre de genre observé ?","a":"<p>Environ <strong>10 %</strong> des adultes en France ont une consommation quotidienne d'alcool. On observe une nette prédominance masculine, avec un ratio de <strong>3 hommes pour 1 femme</strong>.</p>"},{"i":"c610a54a614f","n":76,"o":"76-1","u":"Épidémiologie","t":"Connaître les principaux chiffres liés à la consommation d’alcool en France (sources BEH 2019)","q":"Quelle est la fréquence de consommation d'alcool au moins une fois par an chez les adultes en France, et comment la France se positionne-t-elle au niveau mondial ?","a":"<p>En France, <strong>90 %</strong> des adultes déclarent une consommation d’alcool au moins une fois par an. La France figure parmi les <strong>pays à plus forte consommation</strong> d'alcool au monde.</p>"},{"i":"15861ffa1605","n":76,"o":"76-10","u":"Diagnostic positif","t":"Connaître les principales complications sociales du mésusage d’alcool et le lien avec la précarité","q":"Quel est le lien entre les troubles liés à l'usage d'alcool et la précarité ?","a":"Il existe un <strong>cercle vicieux</strong> : les troubles liés à l'usage d'alcool sont un facteur de risque de <strong>précarité</strong>, et réciproquement, la précarité favorise la <strong>rechute</strong>. Ce lien doit être identifié dans la prise en charge."},{"i":"5563cfd41cf7","n":76,"o":"76-10","u":"Diagnostic positif","t":"Connaître les principales complications sociales du mésusage d’alcool et le lien avec la précarité","q":"Quelles sont les complications sociales du mésusage d'alcool touchant les domaines financier et judiciaire ?","a":"Les complications du mésusage d'alcool sont :\n<ul>\n<li><strong>Financières</strong> : <strong>dettes</strong>, négligence des obligations administratives, problèmes de logement.</li>\n<li><strong>Judiciaires</strong> : <strong>conduite en état d'ivresse</strong>, ivresse publique manifeste, violences ou délits sous l'effet de l'alcool.</li>\n</ul>"},{"i":"5b8b70cf13d5","n":76,"o":"76-10","u":"Diagnostic positif","t":"Connaître les principales complications sociales du mésusage d’alcool et le lien avec la précarité","q":"Quelles sont les complications sociales du mésusage d'alcool touchant le domaine professionnel ?","a":"Les complications professionnelles du mésusage d'alcool incluent :\n<ul>\n<li>Les <strong>avertissements</strong> et <strong>licenciements</strong>.</li>\n<li>L'<strong>absentéisme</strong>.</li>\n<li>Le <strong>chômage</strong>.</li>\n</ul>"},{"i":"c8b2e59c0710","n":76,"o":"76-10","u":"Diagnostic positif","t":"Connaître les principales complications sociales du mésusage d’alcool et le lien avec la précarité","q":"Quelles sont les complications sociales du mésusage d'alcool touchant le domaine familial ?","a":"Les complications familiales du mésusage d'alcool incluent :\n<ul>\n<li>Les <strong>violences intrafamiliales</strong> (psychologiques ou physiques).</li>\n<li>Les <strong>séparations</strong>.</li>\n<li>La <strong>mise en danger de l'enfance</strong>.</li>\n</ul>"},{"i":"51247110eedd","n":76,"o":"76-11","u":"Examens complémentaires","t":"Connaître les marqueurs biologiques usuels de consommation d’alcool : alcoolémie, GGT, volume globulaire moyen (VGM), transferrine désialysée","q":"Quelle est l'utilité des marqueurs biologiques dans le contexte de l'addiction à l'alcool et quel est le piège classique associé ?","a":"<p>Les marqueurs biologiques servent à <ul><li>Objectiver un <strong>mésusage</strong> d'alcool</li><li>Dépister des <strong>complications</strong></li><li>Suivre la pathologie (ex: <strong>rechute</strong>)</li><li>À des fins <strong>motivationnelles</strong></li><li>Dans un cadre <strong>médico-réglementaire</strong></li></ul></p><p>Le piège classique est qu'un <strong>bilan biologique normal n'élimine pas une consommation à risque</strong>.</p>"},{"i":"59241cac26e0","n":76,"o":"76-11","u":"Examens complémentaires","t":"Connaître les marqueurs biologiques usuels de consommation d’alcool : alcoolémie, GGT, volume globulaire moyen (VGM), transferrine désialysée","q":"Comment la Carbohydrate-Deficient Transferrin (CDT), ou transferrine désialylée, se distingue-t-elle comme marqueur de consommation d'alcool ?","a":"<p>La <strong>CDT</strong> est un marqueur <strong>très spécifique</strong> et possède une meilleure sensibilité que les autres. Sa normalisation survient en <strong>2 à 5 semaines</strong>. C'est un <strong>bon marqueur de rechute</strong>. Elle est souvent <strong>onéreuse</strong> et principalement utilisée en cadre <strong>médico-réglementaire</strong> ou en cas de <strong>banalisation/déni</strong>.</p>"},{"i":"a03e0a84b550","n":76,"o":"76-11","u":"Examens complémentaires","t":"Connaître les marqueurs biologiques usuels de consommation d’alcool : alcoolémie, GGT, volume globulaire moyen (VGM), transferrine désialysée","q":"Comment interpréter les Gamma-Glutamyl Transférases (GGT) et le Volume Globulaire Moyen (VGM) comme marqueurs de consommation d'alcool ?","a":"<p>Les <strong>GGT</strong> sont un marqueur de consommation et de souffrance hépatique. Leur sensibilité et spécificité sont <strong>médiocres</strong>. Elles commencent à baisser dès la <strong>première semaine d'arrêt</strong> et se normalisent en <strong>4 à 10 semaines</strong>.</p><p>Le <strong>VGM</strong> est le marqueur le <strong>moins sensible</strong> mais est assez spécifique. Sa normalisation est lente, prenant environ <strong>3 mois</strong> après l'arrêt de la consommation.</p>"},{"i":"d37cc0880702","n":76,"o":"76-11","u":"Examens complémentaires","t":"Connaître les marqueurs biologiques usuels de consommation d’alcool : alcoolémie, GGT, volume globulaire moyen (VGM), transferrine désialysée","q":"Quelles sont les caractéristiques de l'alcoolémie comme marqueur de consommation d'alcool, y compris les repères médico-légaux ?","a":"<p>L'alcoolémie est le reflet d'une <strong>consommation récente</strong>. Les repères médico-légaux sont :</p><ul><li><strong>Contravention</strong> si &gt; <strong>0,5 g/L</strong> dans le sang (ou &gt; 0,25 mg/L dans l'air expiré)</li><li><strong>Délit</strong> si &gt; <strong>0,8 g/L</strong> dans le sang (ou &gt; 0,4 mg/L dans l'air expiré)</li></ul>"},{"i":"0081df0148c7","n":76,"o":"76-12","u":"Diagnostic positif","t":"Connaître les complications médicales générales principales de la consommation d’alcool","q":"Quels sont les principaux cancers dont le risque est augmenté par la consommation d'alcool, et leurs localisations spécifiques ?","a":"<p>L'alcool est la <strong>deuxième cause de mortalité évitable par cancer</strong>. Le risque augmente de façon linéaire avec la dose, sans seuil, et il y a une synergie avec le tabac pour les cancers des VADS. Les localisations à risque fort sont :</p><ul><li>Les <strong>VADS</strong> (bouche, pharynx, larynx).</li><li>L'<strong>œsophage</strong> (carcinome épidermoïde).</li><li>Le <strong>foie</strong> (carcinome hépatocellulaire).</li></ul><p>D'autres localisations concernées incluent l'estomac, le sein et le côlon-rectum.</p>"},{"i":"19ce80ca6c5e","n":76,"o":"76-12","u":"Diagnostic positif","t":"Connaître les complications médicales générales principales de la consommation d’alcool","q":"Quelles sont les principales encéphalopathies et troubles cognitifs spécifiques liés à l'alcool ou à ses carences associées ?","a":"<ul><li><strong>Encéphalopathies</strong> :<ul><li><strong>Encéphalopathie de Gayet-Wernicke</strong> (carence en <strong>vitamine B1</strong>).</li><li>Encéphalopathie pellagreuse (carence en vitamine PP).</li><li>Encéphalopathie hépatique.</li></ul></li><li><strong>Troubles cognitifs</strong> :<ul><li><strong>Syndrome de Korsakoff</strong> (amnésie antérograde, fausses reconnaissances, fabulations).</li><li>Maladie de Marchiafava-Bignami (démyélinisation du corps calleux).</li></ul></li></ul>"},{"i":"5b663e32ea2f","n":76,"o":"76-12","u":"Diagnostic positif","t":"Connaître les complications médicales générales principales de la consommation d’alcool","q":"Quelles sont les complications neurologiques périphériques et musculaires de l'alcoolisme chronique ?","a":"<ul><li><strong>Cervelet</strong> : <strong>atrophie cérébelleuse</strong> (vermis), se manifestant par une ataxie statique et locomotrice.</li><li><strong>Nerfs périphériques</strong> : <strong>polyneuropathie longueur-dépendante</strong> (2<sup>e</sup> cause après le diabète), neuropathie optique alcoolo-tabagique.</li><li><strong>Muscle</strong> : myopathie aiguë (rhabdomyolyse) et myopathie chronique (faiblesse proximale).</li></ul>"},{"i":"702b4def2400","n":76,"o":"76-12","u":"Diagnostic positif","t":"Connaître les complications médicales générales principales de la consommation d’alcool","q":"Comment prévenir systématiquement les carences vitaminiques chez un patient alcoolique hospitalisé ?","a":"<p>Chez tout patient alcoolique hospitalisé, quelle qu'en soit la raison, il est essentiel d'initier une <strong>supplémentation vitaminique systématique</strong> comprenant <strong>B1 + B6 + B12 + folates + PP</strong>. Il est crucial de ne <strong>jamais administrer de sérum glucosé sans vitamine B1</strong> chez un alcoolique pour ne pas déclencher une encéphalopathie de Gayet-Wernicke.</p>"},{"i":"8ae62f2c668a","n":76,"o":"76-12","u":"Diagnostic positif","t":"Connaître les complications médicales générales principales de la consommation d’alcool","q":"Quelles sont les complications cardiovasculaires, hématologiques et métaboliques de la consommation chronique d'alcool ?","a":"<ul><li><strong>Cardiovasculaires</strong> : HTA, troubles du rythme, <strong>cardiomyopathie dilatée non obstructive</strong>, insuffisance cardiaque gauche.</li><li><strong>Hématologiques</strong> : <strong>macrocytose</strong>, anémie, thrombopénie, leucopénie.</li><li><strong>Métaboliques</strong> : hypoglycémie, <strong>acidocétose alcoolique</strong>, dénutrition (risque de syndrome de renutrition), hypertriglycéridémie, hyperuricémie / goutte, hypokaliémie, hyponatrémie.</li></ul>"},{"i":"93a5798a4f11","n":76,"o":"76-12","u":"Diagnostic positif","t":"Connaître les complications médicales générales principales de la consommation d’alcool","q":"Quelle est la triade clinique et l'aspect IRM caractéristique de l'encéphalopathie de Gayet-Wernicke ?","a":"<p>La triade clinique de l'encéphalopathie de Gayet-Wernicke (due à une carence en vitamine B1) est :</p><ul><li><strong>Syndrome confusionnel</strong>.</li><li><strong>Syndrome cérébelleux statique</strong>.</li><li><strong>Signes oculomoteurs</strong> (paralysie oculomotrice, nystagmus).</li></ul><p>À l'<strong>IRM cérébrale</strong>, les signes caractéristiques sont des <strong>hypersignaux FLAIR des corps mamillaires</strong>, témoignant d'une carence aiguë en vitamine B1.</p>"},{"i":"a9832efae821","n":76,"o":"76-12","u":"Diagnostic positif","t":"Connaître les complications médicales générales principales de la consommation d’alcool","q":"Quelles sont les principales complications digestives de l'alcool, spécifiquement au niveau du foie et du pancréas ?","a":"<ul><li><strong>Foie</strong> : <strong>stéatose</strong> (lésion la plus précoce, réversible), hépatite alcoolique aiguë, <strong>cirrhose micronodulaire</strong>.</li><li><strong>Pancréas</strong> : pancréatite aiguë, <strong>pancréatite chronique calcifiante</strong>.</li><li><strong>Intestin</strong> : Diarrhée motrice et/ou par atteinte entérocytaire.</li></ul>"},{"i":"55df415d4c57","n":76,"o":"76-13","u":"Définition","t":"Connaître les principes de base de la prévention primaire du mésusage d’alcool","q":"Quelle est la définition de la prévention primaire du mésusage d'alcool ?","a":"<p>La prévention primaire du mésusage d'alcool vise à <strong>éviter</strong> ou <strong>retarder la première consommation</strong> de substances psychoactives.</p>"},{"i":"5b794c1127a6","n":76,"o":"76-13","u":"Définition","t":"Connaître les principes de base de la prévention primaire du mésusage d’alcool","q":"Quels sont les objectifs de la prévention primaire du mésusage d'alcool ?","a":"<ul><li>Empêcher l'entrée dans la consommation d'alcool.</li><li>Retarder l'âge de début de la consommation d'alcool.</li></ul>"},{"i":"b0a971502f50","n":76,"o":"76-13","u":"Définition","t":"Connaître les principes de base de la prévention primaire du mésusage d’alcool","q":"Comment différencier la prévention primaire et la prévention secondaire du mésusage d'alcool ?","a":"<p>La prévention primaire intervient <strong>avant toute consommation</strong> d'alcool. La prévention secondaire, quant à elle, concerne le <strong>repérage précoce et l'intervention brève (RPIB)</strong>, s'adressant à un mésusage d'alcool déjà installé.</p>"},{"i":"ce66f13b089d","n":76,"o":"76-13","u":"Définition","t":"Connaître les principes de base de la prévention primaire du mésusage d’alcool","q":"Quels sont les outils principaux de la prévention primaire du mésusage d'alcool ?","a":"<p>Les outils principaux de la prévention primaire du mésusage d'alcool sont l'<strong>information</strong> et l'<strong>éducation</strong> des futurs usagers.</p>"},{"i":"1ff80c3231a0","n":76,"o":"76-15","u":"Prise en charge","t":"Connaître les principes de la prise en charge","q":"Quels sont les moyens thérapeutiques utilisés dans la prise en charge de l'addiction à l'alcool ?","a":"<ul><li>L'<strong>entretien motivationnel</strong>, qui est central.</li><li>Le <strong>soutien psychologique</strong> et les <strong>thérapies cognitivo-comportementales (TCC)</strong>.</li><li>Les <strong>groupes d'entraide</strong>.</li><li>Les <strong>traitements pharmacologiques</strong>, en complément des autres approches.</li></ul>"},{"i":"271b05af100f","n":76,"o":"76-15","u":"Prise en charge","t":"Connaître les principes de la prise en charge","q":"Quel est le principe général de la prise en charge de l'addiction à l'alcool ?","a":"<p>La prise en charge de l'addiction à l'alcool doit être <strong>globale</strong>, <strong>médico-psycho-sociale</strong> et <strong>pluridisciplinaire</strong>.</p>"},{"i":"464562751dfd","n":76,"o":"76-15","u":"Prise en charge","t":"Connaître les principes de la prise en charge","q":"Quelles sont les modalités d'orientation pour un sevrage de l'alcool et leurs indications principales ?","a":"<ul><li>Le <strong>sevrage ambulatoire</strong> est le plus fréquent (environ <strong>80 %</strong> des cas) et le plus réaliste.</li><li>Le <strong>sevrage hospitalier</strong> (environ <strong>20 %</strong> des cas) est indiqué selon des critères <strong>alcoologiques</strong>, <strong>somatiques</strong>, <strong>psychiatriques</strong> et <strong>socio-environnementaux</strong>.</li></ul>"},{"i":"778fc54c043e","n":76,"o":"76-15","u":"Prise en charge","t":"Connaître les principes de la prise en charge","q":"Quelles sont les stratégies possibles pour atteindre les objectifs de prise en charge de l'addiction à l'alcool ?","a":"<ul><li>Un <strong>arrêt complet et encadré</strong> (sevrage) suivi du maintien de l'abstinence.</li><li>Une <strong>diminution progressive</strong> de la consommation jusqu'à un usage à faible risque ou un arrêt.</li></ul>"},{"i":"acc8114191df","n":76,"o":"76-15","u":"Prise en charge","t":"Connaître les principes de la prise en charge","q":"Quels objectifs peuvent être définis par le patient dans la prise en charge de l'addiction à l'alcool ?","a":"<ul><li>L'<strong>arrêt complet</strong> (le plus réaliste en cas de dépendance sévère).</li><li>Le retour à un <strong>usage à faible risque</strong>.</li><li>La <strong>réduction des consommations</strong> dans une logique de réduction des risques.</li></ul>"},{"i":"1f354bc87b66","n":76,"o":"76-16","u":"Prise en charge","t":"Connaître les principes de l’entretien motivationnel","q":"Quels sont les différents stades du changement selon Prochaska & DiClemente, applicables à l'entretien motivationnel ?","a":"<p>La motivation n'est pas un trait immuable mais un état fluctuant. Les <strong>6 étapes</strong> sont :</p><ul><li>Pré-contemplation</li><li>Contemplation</li><li>Détermination</li><li>Action</li><li>Maintien</li><li>Rechute (qui peut relancer le cycle sans sentiment d'échec)</li></ul>"},{"i":"404925cbe3a0","n":76,"o":"76-16","u":"Prise en charge","t":"Connaître les principes de l’entretien motivationnel","q":"Quelle est la définition de l'entretien motivationnel dans la prise en charge des conduites addictives ?","a":"<p>L'entretien motivationnel est un style d'entretien <strong>collaboratif et participatif</strong>, centré sur la personne, qui vise à renforcer la motivation propre (intrinsèque) au changement et l'engagement vers celui-ci, renforcer l'adhésion à la prise en charge et explorer et résoudre l'ambivalence du patient.</p>"},{"i":"8f6e1de01eba","n":76,"o":"76-16","u":"Prise en charge","t":"Connaître les principes de l’entretien motivationnel","q":"Quels sont les principes pratiques de l'entretien motivationnel en addictologie, synthétisés par l'acronyme VICTOIRE ?","a":"<ul><li><strong>V</strong>aloriser : Toute action, même mineure, en faveur du changement.</li><li><strong>I</strong>ntéresser : Susciter l'intérêt du patient sur le changement et son ambivalence.</li><li><strong>C</strong>omprendre : Montrer une démarche empathique de compréhension.</li><li><strong>T</strong>olérer : Les résistances, avec un jugement positif inconditionnel.</li><li><strong>O</strong>uvrir : Favoriser les questions ouvertes.</li><li><strong>I</strong>nsister : Sur l'ambivalence sans prendre parti ni argumenter.</li><li><strong>R</strong>eformuler : Le discours du patient (empathie).</li><li><strong>É</strong>couter : Se laisser informer par le patient sur ses propres représentations.</li></ul>"},{"i":"9c98d7abd0fc","n":76,"o":"76-16","u":"Prise en charge","t":"Connaître les principes de l’entretien motivationnel","q":"Quel est l'esprit général de l'entretien motivationnel en addictologie ?","a":"<p>Il ne s'agit pas de convaincre le patient de changer, mais d'explorer avec lui, de façon <strong>empathique et sans jugement</strong>, les avantages et inconvénients de ses comportements. L'objectif est de préserver le sentiment d'autonomie et de liberté du patient et de valoriser toute action, même mineure, en faveur du changement pour renforcer son sentiment d'efficacité personnelle.</p>"},{"i":"0262847e70e8","n":76,"o":"76-2","u":"Définition","t":"Connaître les définitions : addictologie, non usage, usage à faible risque, mésusage, usage à risque, usage nocif (CIM11), dépendance (CIM 11)","q":"Selon la CIM11, quels sont les critères diagnostiques de la dépendance à l'alcool ?","a":"<p>Selon la CIM11, la dépendance à l'alcool est un syndrome caractérisé par un ensemble de phénomènes comportementaux, cognitifs et physiologiques où l'usage d'alcool entraîne un <strong>désinvestissement progressif des autres activités</strong>. Le diagnostic est posé si <strong>au moins 3 critères sur 6 sont présents sur une période de 12 mois</strong>. Ceci correspond au trouble de l'usage DSM-5 modéré à sévère.</p>"},{"i":"4267cc5f7947","n":76,"o":"76-2","u":"Définition","t":"Connaître les définitions : addictologie, non usage, usage à faible risque, mésusage, usage à risque, usage nocif (CIM11), dépendance (CIM 11)","q":"Selon la CIM11, qu'est-ce que l'usage nocif d'alcool ?","a":"<p>Selon la CIM11, l'usage nocif d'alcool est un mode de consommation <strong>préjudiciable à la santé</strong>, avec des <strong>complications physiques ou psychiques avérées</strong>, mais <strong>sans remplir les critères de la dépendance</strong>. C'est un trouble lié à l'usage, mais pas une addiction au sens propre.</p>"},{"i":"793b6a3dfd71","n":76,"o":"76-2","u":"Définition","t":"Connaître les définitions : addictologie, non usage, usage à faible risque, mésusage, usage à risque, usage nocif (CIM11), dépendance (CIM 11)","q":"Quelle est la définition de l'addictologie ?","a":"<p>L'addictologie est la discipline médicale qui prend en charge les <strong>conduites addictives</strong>.</p>"},{"i":"8c53e1f2d021","n":76,"o":"76-2","u":"Définition","t":"Connaître les définitions : addictologie, non usage, usage à faible risque, mésusage, usage à risque, usage nocif (CIM11), dépendance (CIM 11)","q":"Qu'est-ce que l'usage à faible risque d'alcool et quels sont les repères de consommation associés ?","a":"<p>L'usage à faible risque d'alcool est une consommation qui respecte les repères suivants : <ul><li><strong>moins de 10 verres standard par semaine</strong></li><li><strong>moins de 2 verres standard par jour</strong></li><li>avec des <strong>jours sans consommation</strong>.</li></ul></p>"},{"i":"a46829282787","n":76,"o":"76-2","u":"Définition","t":"Connaître les définitions : addictologie, non usage, usage à faible risque, mésusage, usage à risque, usage nocif (CIM11), dépendance (CIM 11)","q":"Comment définit-on le mésusage d'alcool ?","a":"<p>Le mésusage d'alcool désigne toute consommation <strong>supérieure aux repères de l'usage à faible risque</strong>. Il est caractérisé par l'existence de <strong>risques</strong>, de <strong>dommages</strong> et/ou de <strong>dépendance</strong>. Il se décline en usage à risque, usage nocif et dépendance.</p>"},{"i":"bb0260898d53","n":76,"o":"76-2","u":"Définition","t":"Connaître les définitions : addictologie, non usage, usage à faible risque, mésusage, usage à risque, usage nocif (CIM11), dépendance (CIM 11)","q":"Dans le cadre de la consommation d'alcool, qu'est-ce que le non-usage et dans quelles situations est-il recommandé ?","a":"<p>Le non-usage correspond aux situations où il est recommandé de <strong>ne pas consommer d'alcool</strong>. Il s'applique notamment aux <ul><li>femmes enceintes ou en projet de grossesse, et celles qui allaitent</li><li>jeunes et adolescents</li><li>situations de conduite automobile, de manipulation d'outils ou de machines</li><li>pratique de sports à risque</li><li>prise de certains médicaments ou en présence de pathologies spécifiques.</li></ul></p>"},{"i":"c83d63b88268","n":76,"o":"76-2","u":"Définition","t":"Connaître les définitions : addictologie, non usage, usage à faible risque, mésusage, usage à risque, usage nocif (CIM11), dépendance (CIM 11)","q":"Quelle est la définition de l'usage à risque d'alcool ?","a":"<p>L'usage à risque d'alcool correspond aux niveaux de consommation qui exposent à des <strong>complications (aiguës ou chroniques) non encore présentes</strong>. Ce n'est pas un trouble médical en soi, mais un <strong>facteur de risque pré-morbide</strong> (selon l'OMS) qu'il convient de repérer.</p>"},{"i":"256a93ffb5b4","n":76,"o":"76-3","u":"Définition","t":"Connaître les éléments de comparaison de la dépendance (CIM 11) et du trouble de l’usage de l’alcool (DSM5)","q":"Comment les niveaux de sévérité du trouble de l'usage de l'alcool (DSM-5) se corrèlent-ils avec les catégories de la CIM-11 ?","a":"<ul><li>Un <strong>trouble léger</strong> (2 à 3 critères DSM-5) correspond approximativement à l'<strong>usage nocif</strong> de la CIM-11.</li><li>Un <strong>trouble modéré à sévère</strong> (4 à 5 critères DSM-5 ou ≥ 6 critères DSM-5) correspond au <strong>syndrome de dépendance</strong> de la CIM-11 (≥ 3 critères sur 6).</li></ul>"},{"i":"2e0869661dd0","n":76,"o":"76-3","u":"Définition","t":"Connaître les éléments de comparaison de la dépendance (CIM 11) et du trouble de l’usage de l’alcool (DSM5)","q":"Quels sont les sept critères du DSM-5 partagés avec les critères de dépendance de la CIM-11 pour le trouble de l'usage de l'alcool ?","a":"<ul><li>Consommation persistante malgré des problèmes physiques/psychiatriques (partagé avec \"poursuite malgré conséquences nocives\" CIM).</li><li>Perte de contrôle : quantité/durée supérieure aux prévisions (partagé avec \"difficultés à contrôler l'usage\" CIM).</li><li>Désir/tentatives infructueuses de réduire ou contrôler (partagé avec \"difficultés à contrôler l'usage\" CIM).</li><li>Temps considérable consacré à la consommation/récupération (partagé avec \"abandon des autres intérêts\" CIM).</li><li>Abandon/réduction d'activités importantes au profit de l'alcool (partagé avec \"abandon des autres intérêts\" CIM).</li><li>Tolérance/accoutumance.</li><li>Sevrage à l'arrêt.</li><li>Craving : envie impérieuse, pulsion irrépressible (partagé avec \"désir puissant/compulsif\" CIM).</li></ul>"},{"i":"4a91e557c54d","n":76,"o":"76-3","u":"Définition","t":"Connaître les éléments de comparaison de la dépendance (CIM 11) et du trouble de l’usage de l’alcool (DSM5)","q":"Quelle est l'approche du DSM-5 pour la classification des problèmes liés à l'alcool ?","a":"<p>Le DSM-5 définit un <strong>trouble de l'usage de l'alcool</strong> comme un <strong>continuum de sévérité</strong>, basé sur <strong>11 critères</strong> évalués sur une période de <strong>12 mois</strong>.</p>"},{"i":"6c9a34662e69","n":76,"o":"76-3","u":"Définition","t":"Connaître les éléments de comparaison de la dépendance (CIM 11) et du trouble de l’usage de l’alcool (DSM5)","q":"Comment la Classification Internationale des Maladies (CIM-11) catégorise-t-elle les problèmes liés à l'alcool ?","a":"<p>La CIM-11 distingue deux catégories principales : l'<strong>usage nocif</strong> et le <strong>syndrome de dépendance</strong>. Ce dernier est un diagnostic catégoriel posé à partir de <strong>3 critères sur 6</strong>.</p>"},{"i":"776820d6f05b","n":76,"o":"76-4","u":"Diagnostic positif","t":"Connaître les repères de consommation d’alcool définissant l’usage à faible risque","q":"Selon les recommandations de Santé publique France, quel est le repère hebdomadaire de consommation d'alcool définissant un usage à faible risque ?","a":"<p>Il est recommandé de ne pas consommer plus de <strong>10 verres standard par semaine</strong>.</p>"},{"i":"9766a80ab2b4","n":76,"o":"76-4","u":"Diagnostic positif","t":"Connaître les repères de consommation d’alcool définissant l’usage à faible risque","q":"Selon les recommandations de Santé publique France, quel est le repère quotidien de consommation d'alcool définissant un usage à faible risque ?","a":"<p>Il est recommandé de ne pas consommer plus de <strong>2 verres standard par jour</strong>.</p>"},{"i":"e31c8b31b2be","n":76,"o":"76-4","u":"Diagnostic positif","t":"Connaître les repères de consommation d’alcool définissant l’usage à faible risque","q":"Quels sont les repères de consommation d'alcool définissant un usage à faible risque, au-delà de la quantité hebdomadaire et quotidienne ?","a":"<p>Il est recommandé d'avoir des <strong>jours sans consommation</strong> d'alcool dans la semaine.</p>"},{"i":"ec57a24ab229","n":76,"o":"76-4","u":"Diagnostic positif","t":"Connaître les repères de consommation d’alcool définissant l’usage à faible risque","q":"Quelles sont les recommandations complémentaires de Santé publique France pour réduire les risques lors d'une consommation occasionnelle d'alcool ?","a":"<ul><li>Réduire la quantité totale d’alcool bue à chaque occasion.</li><li>Boire lentement, en mangeant et en alternant avec de l’eau.</li><li>Éviter les lieux et activités à risque.</li><li>S’assurer de la présence de personnes de confiance et d’un retour sécurisé.</li></ul>"},{"i":"8a44a895baaa","n":76,"o":"76-5","u":"Diagnostic positif","t":"Savoir diagnostiquer usage nocif et dépendance selon les critères de la CIM 11","q":"Quelle est la définition du syndrome de dépendance à l'alcool selon la CIM 11 ?","a":"<p>Le syndrome de dépendance à l'alcool est un ensemble de phénomènes comportementaux, cognitifs et physiologiques conduisant à un <strong>désinvestissement progressif des autres activités</strong> au profit de l'usage de la substance.</p>"},{"i":"c43b48bedd31","n":76,"o":"76-5","u":"Diagnostic positif","t":"Savoir diagnostiquer usage nocif et dépendance selon les critères de la CIM 11","q":"Quels sont les six critères diagnostiques de la dépendance à l'alcool selon la CIM 11 ?","a":"<p>Le diagnostic de certitude d'un syndrome de dépendance à l'alcool est posé si <strong>au moins 3 de ces 6 manifestations</strong> sont présentes ensemble au cours de la dernière année :</p><ul><li><strong>Craving</strong> : désir puissant ou compulsif d'utiliser la substance.</li><li>Difficultés à contrôler l'usage (début, interruption, niveaux de consommation).</li><li><strong>Syndrome de sevrage physiologique</strong> à la diminution ou l'arrêt (ou usage pour soulager/éviter le sevrage).</li><li><strong>Tolérance</strong> : besoin d'une quantité plus importante pour obtenir l'effet désiré.</li><li>Abandon progressif des autres sources de plaisir et d'intérêts au profit de l'usage ; temps croissant passé à se procurer/consommer la substance ou à récupérer de ses effets.</li><li>Poursuite de la consommation malgré des <strong>conséquences manifestement nocives</strong> (dont le sujet est, ou devrait être, conscient).</li></ul>"},{"i":"d6aecc51484e","n":76,"o":"76-5","u":"Diagnostic positif","t":"Savoir diagnostiquer usage nocif et dépendance selon les critères de la CIM 11","q":"Comment est défini l'usage nocif à l'alcool selon la CIM 11 ?","a":"<p>L'usage nocif à l'alcool est défini par un mode de consommation préjudiciable à la santé, entraînant des <strong>complications physiques, psychiques ou sociales avérées</strong>, sans répondre aux critères du syndrome de dépendance. Le patient ne fait souvent pas le lien entre le dommage et sa consommation.</p>"},{"i":"10c4fbe6a001","n":76,"o":"76-6","u":"Diagnostic positif","t":"Savoir dépister un mésusage d’alcool : verres standards, consommation déclarée, AUDIT-C","q":"Quelles sont les trois questions du questionnaire AUDIT-C utilisées pour le dépistage du mésusage d'alcool ?","a":"<p>Les trois questions du questionnaire AUDIT-C sont :</p><ul><li>La <strong>fréquence de consommation</strong> d'alcool.</li><li>Le <strong>nombre de verres un jour ordinaire</strong> de consommation.</li><li>La <strong>fréquence des épisodes de consommation de 6 verres ou plus</strong> en une occasion.</li></ul>"},{"i":"2eb00ef40ee9","n":76,"o":"76-6","u":"Diagnostic positif","t":"Savoir dépister un mésusage d’alcool : verres standards, consommation déclarée, AUDIT-C","q":"Quels signes cliniques du faciès peuvent évoquer un mésusage chronique d'alcool ?","a":"<p>Les signes cliniques du faciès pouvant évoquer un mésusage chronique d'alcool incluent :</p><ul><li>Un <strong>faciès vultueux</strong>.</li><li>Une <strong>couperose</strong> du visage.</li><li>Parfois, un <strong>rhinophyma</strong>.</li></ul>"},{"i":"5bcef4ba9c4e","n":76,"o":"76-6","u":"Diagnostic positif","t":"Savoir dépister un mésusage d’alcool : verres standards, consommation déclarée, AUDIT-C","q":"Qu'est-ce qu'une alcoolisation ponctuelle importante (API) dans le cadre du dépistage du mésusage d'alcool ?","a":"<p>Une alcoolisation ponctuelle importante (API) est définie par la consommation de <strong>6 verres standard ou plus en une seule occasion</strong>.</p>"},{"i":"6e57c9fedc11","n":76,"o":"76-6","u":"Diagnostic positif","t":"Savoir dépister un mésusage d’alcool : verres standards, consommation déclarée, AUDIT-C","q":"Comment quantifier précisément la consommation d'alcool pur d'un patient ?","a":"<p>La méthode précise pour quantifier l'alcool pur consommé est : quantité (en Litres) × 8 × degré d'alcool.</p><p>Par exemple, une bouteille de <strong>75 cl de vin à 12,5°</strong> représente 0,75 L × 8 × 12,5 = <strong>75 g d'alcool pur</strong>.</p>"},{"i":"c79f6c58fa57","n":76,"o":"76-6","u":"Diagnostic positif","t":"Savoir dépister un mésusage d’alcool : verres standards, consommation déclarée, AUDIT-C","q":"Comment interpréter les scores de l'AUDIT-C pour les femmes en termes de consommation à risque et d'alcoolodépendance probable ?","a":"<p>Pour les femmes, l'interprétation de l'AUDIT-C est la suivante :</p><ul><li>Un score <strong>égal ou supérieur à 3</strong> indique une <strong>consommation à risque</strong> pour la santé.</li><li>Un score <strong>égal ou supérieur à 4</strong> suggère une <strong>alcoolodépendance probable</strong>.</li></ul>"},{"i":"cbb7669efe36","n":76,"o":"76-6","u":"Diagnostic positif","t":"Savoir dépister un mésusage d’alcool : verres standards, consommation déclarée, AUDIT-C","q":"Comment interpréter les scores de l'AUDIT-C pour les hommes en termes de consommation à risque et d'alcoolodépendance probable ?","a":"<p>Pour les hommes, l'interprétation de l'AUDIT-C est la suivante :</p><ul><li>Un score <strong>égal ou supérieur à 4</strong> indique une <strong>consommation à risque</strong> pour la santé.</li><li>Un score <strong>égal ou supérieur à 5</strong> suggère une <strong>alcoolodépendance probable</strong>.</li></ul>"},{"i":"e49a5e113424","n":76,"o":"76-6","u":"Diagnostic positif","t":"Savoir dépister un mésusage d’alcool : verres standards, consommation déclarée, AUDIT-C","q":"Comment le dépistage d'un mésusage de l'alcool peut-il s'appuyer sur la consommation déclarée d'alcool (CDA) ?","a":"<p>La consommation déclarée d'alcool (CDA) s'évalue en demandant au patient sa consommation <strong>hebdomadaire ou quotidienne</strong>. Il est important de distinguer :</p><ul><li>Les jours ouvrés et les jours de repos.</li><li>Les écarts de consommation par rapport à la consommation habituelle.</li></ul>"},{"i":"1764fef1083a","n":76,"o":"76-7","u":"Diagnostic positif","t":"Savoir rechercher et reconnaître les signes d’un syndrome de sevrage à l’alcool et les accidents de sevrage (convulsions et delirium tremens)","q":"Comment définir le syndrome de sevrage à l'alcool et quel est son mécanisme physiopathologique sous-jacent ?","a":"<p>Le syndrome de sevrage à l'alcool correspond à l'ensemble des signes et symptômes qui apparaissent chez un sujet dépendant lorsque l'alcoolémie décroît ou s'annule. Physiopathologiquement, l'alcool étant un agoniste des récepteurs GABA (inhibiteurs), son arrêt brutal entraîne une baisse de la transmission GABAergique, provoquant une <strong>hyperexcitabilité neuronale</strong>.</p>"},{"i":"7d134e0b7ad8","n":76,"o":"76-7","u":"Diagnostic positif","t":"Savoir rechercher et reconnaître les signes d’un syndrome de sevrage à l’alcool et les accidents de sevrage (convulsions et delirium tremens)","q":"Quels sont les délais et les manifestations cliniques les plus évocatrices du syndrome de sevrage à l'alcool non compliqué ?","a":"<p>Les premiers symptômes du syndrome de sevrage à l'alcool apparaissent généralement <strong>6 à 48 heures</strong> après l'arrêt (souvent le matin au réveil) et sont au maximum dans les 72 premières heures, pouvant aller jusqu'à 7-10 jours. En l'absence de complication, les symptômes régressent en 2 à 5 jours. Les manifestations les plus évocatrices sont :</p><ul><li><strong>Tremblements</strong></li><li><strong>Sueurs profuses</strong></li><li><strong>Anxiété</strong></li><li><strong>Vomissements</strong></li></ul>"},{"i":"a8824016a179","n":76,"o":"76-7","u":"Diagnostic positif","t":"Savoir rechercher et reconnaître les signes d’un syndrome de sevrage à l’alcool et les accidents de sevrage (convulsions et delirium tremens)","q":"Quels sont les différents niveaux de sévérité des manifestations du syndrome de sevrage à l'alcool et quels sont les deux accidents de sevrage potentiels ?","a":"<p>Les différents niveaux de sévérité du syndrome de sevrage à l'alcool sont :</p><ul><li><strong>Niveau 1</strong> : Hyperactivité neurovégétative (sueurs, tachycardie)</li><li><strong>Niveau 2</strong> : Trouble de l'attention, hallucinations</li><li><strong>Niveau 3</strong> : Convulsions</li><li><strong>Niveau 4</strong> : Delirium tremens (agitation majeure surajoutée)</li></ul><p>Les deux accidents de sevrage potentiels, si le syndrome n'est pas prévenu ou pris en charge, sont la <strong>crise convulsive</strong> (niveau 3) et le <strong>delirium tremens</strong> (niveau 4).</p>"},{"i":"1d51a60d6650","n":76,"o":"76-8","u":"Identifier une urgence","t":"Savoir diagnostiquer une intoxication alcoolique aiguë avec ou sans coma éthylique (diagnostic différentiel) et rechercher les troubles métaboliques associés","q":"Quels sont les troubles métaboliques à rechercher systématiquement lors d'une intoxication alcoolique aiguë et leurs particularités ?","a":"<p>Les troubles métaboliques à rechercher systématiquement sont :</p><ul><li><strong>Hypoglycémie</strong>, surtout chez l'enfant et l'alcoolique chronique dénutri.</li><li><strong>Acidocétose alcoolique</strong>.</li><li><strong>Hyponatrémie</strong>, fréquente chez les gros buveurs de bière. Attention, il ne faut <strong>pas la corriger trop vite</strong> pour éviter le risque de myélinolyse centropontine.</li><li><strong>Hypothermie</strong>.</li><li><strong>Rhabdomyolyse</strong>.</li></ul>"},{"i":"5102b0b594e5","n":76,"o":"76-8","u":"Identifier une urgence","t":"Savoir diagnostiquer une intoxication alcoolique aiguë avec ou sans coma éthylique (diagnostic différentiel) et rechercher les troubles métaboliques associés","q":"Quel est l'intérêt de la mesure de l'alcoolémie et des examens complémentaires dans le diagnostic d'une intoxication alcoolique aiguë ?","a":"<p>Le diagnostic de l'intoxication alcoolique aiguë étant <strong>clinique</strong>, aucun examen biologique n'est nécessaire au diagnostic initial.</p><ul><li>L'<strong>alcoolémie n'est pas corrélée à la gravité clinique</strong>. Elle est réalisée en cas de tableau atypique ou de doute sur un diagnostic différentiel (autre cause de coma, traumatisme crânien, autre intoxication, hypoglycémie).</li><li>Les examens complémentaires servent principalement à <strong>éliminer un diagnostic différentiel</strong> (ex: Item 336 - Coma non traumatique) ou à <strong>rechercher une complication</strong>.</li></ul>"},{"i":"7246728c3c9f","n":76,"o":"76-8","u":"Identifier une urgence","t":"Savoir diagnostiquer une intoxication alcoolique aiguë avec ou sans coma éthylique (diagnostic différentiel) et rechercher les troubles métaboliques associés","q":"Comment se manifeste une ivresse simple chez l'adulte ?","a":"<p>L'ivresse simple se déroule en deux phases :</p><ul><li>Une phase d'excitation : <strong>agitation motrice</strong>, <strong>logorrhée</strong>, troubles de l'élocution, <strong>haleine œnolique</strong>, troubles de l'équilibre.</li><li>Une phase hyporéactive : <strong>hyporéflexie</strong>, <strong>hypoesthésie</strong>, incontinence urinaire, pouvant aller jusqu'au coma.</li></ul>"},{"i":"f885e0809fb2","n":76,"o":"76-8","u":"Identifier une urgence","t":"Savoir diagnostiquer une intoxication alcoolique aiguë avec ou sans coma éthylique (diagnostic différentiel) et rechercher les troubles métaboliques associés","q":"Quelles sont les caractéristiques d'un coma éthylique non compliqué ?","a":"<p>Le coma éthylique est un <strong>coma calme</strong>, caractérisé par :</p><ul><li><strong>Aréactivité</strong></li><li><strong>Mydriase</strong></li><li><strong>Hypotonie</strong></li><li><strong>Dépression respiratoire</strong></li><li><strong>Hypothermie</strong></li><li><strong>Hypotension</strong></li><li>Absence de signe de localisation.</li></ul><p>Il peut engager le pronostic vital et nécessite une prise en charge en réanimation.</p>"},{"i":"344896fc09e7","n":76,"o":"76-9","u":"Diagnostic positif","t":"Connaître l’association fréquente du mésusage d’alcool avec d’autres pathologies addictives et psychiatriques, qu’elles soient primaires ou secondaires","q":"Quelles sont les comorbidités psychiatriques les plus fréquemment associées au mésusage d'alcool ?","a":"<p>Les comorbidités psychiatriques les plus fréquemment associées au mésusage d'alcool sont les <strong>troubles dépressifs</strong> et les <strong>troubles anxieux</strong>.</p>"},{"i":"cf32592bebf7","n":76,"o":"76-9","u":"Diagnostic positif","t":"Connaître l’association fréquente du mésusage d’alcool avec d’autres pathologies addictives et psychiatriques, qu’elles soient primaires ou secondaires","q":"Quels sont les troubles psychiatriques préexistants particulièrement à risque de présenter un trouble de l'usage d'alcool ?","a":"<p>Les patients atteints de <strong>schizophrénie</strong> (20-30%) et de <strong>trouble bipolaire</strong> (40%) sont particulièrement à risque de présenter un trouble de l'usage d'alcool.</p>"},{"i":"dedb7415fa02","n":76,"o":"76-9","u":"Diagnostic positif","t":"Connaître l’association fréquente du mésusage d’alcool avec d’autres pathologies addictives et psychiatriques, qu’elles soient primaires ou secondaires","q":"Quels sont les autres risques psychiatriques liés au mésusage d'alcool, en dehors des troubles dépressifs et anxieux ?","a":"<p>Outre les troubles dépressifs et anxieux, le mésusage d'alcool peut entraîner un <strong>trouble psychotique induit par une substance</strong>, une <strong>aggravation de troubles psychiatriques préexistants</strong>, et augmente fortement le risque de <strong>conduites suicidaires</strong>, surtout lors des intoxications aiguës.</p>"},{"i":"f0588d9170e9","n":76,"o":"76-9","u":"Diagnostic positif","t":"Connaître l’association fréquente du mésusage d’alcool avec d’autres pathologies addictives et psychiatriques, qu’elles soient primaires ou secondaires","q":"Quelle démarche adopter face à un patient présentant un mésusage d'alcool concernant d'éventuelles autres addictions ?","a":"<p>Face à un mésusage d'alcool, il convient de réaliser un <strong>bilan addictologique complet</strong>. Celui-ci inclut le dépistage systématique des comorbidités addictives en <strong>quantifiant l'usage</strong> et en recherchant des <strong>critères de dépendance</strong> pour les autres substances psychoactives, ainsi que la recherche d'<strong>addictions comportementales</strong>.</p>"}]};